/* === v155-user-profile-flow-lock: stoppa hela dubbla profilflödet ===
   Bas: v152.
   Problem: flera gamla handlers kör Namn -> Lag två gånger.
   Fix: lås hela ensureUserProfile(true)-flödet en kort stund efter att det körts.
   Namn och Lag ska båda visas, men bara en gång vardera.
*/

(function(){
  if(window.__tt155UserProfileFlowLock)return;
  window.__tt155UserProfileFlowLock=true;

  var originalEnsure = (typeof ensureUserProfile==="function") ? ensureUserProfile : null;
  var running=false;
  var lastCompletedAt=0;
  var lastProfile=null;

  function readProfile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      return raw?JSON.parse(raw):null;
    }catch(e){}
    return null;
  }

  function saveProfileDirect(name,team){
    try{
      if(typeof saveUserProfile==="function")return saveUserProfile(name,team);
    }catch(e){}
    name=String(name||"").trim()||"Tränare";
    team=String(team||"").trim().toUpperCase().replace(/\s+/g,"-")||"MITT-LAG";
    var old=readProfile()||{};
    var p={
      ownerId:old.ownerId||("user_"+Math.random().toString(36).slice(2)+Date.now().toString(36)),
      ownerName:name,
      teamId:team,
      teamCode:team,
      teamName:team
    };
    localStorage.setItem("tt_profile_v1",JSON.stringify(p));
    return p;
  }

  function updateAllProfileButtons(p){
    if(!p)return;
    ["btn-profile-team","btn-profile-v59","btn-profile-v61","tt102-profile-btn"].forEach(function(id){
      var b=document.getElementById(id);
      if(b){
        var team=(p.teamCode||p.teamId||"Lag");
        b.textContent="🏷️ "+team;
        b.title="Konto och aktivt lag";
        try{b.classList.add("tt298-team-btn");}catch(e){}
      }
    });
    try{if(typeof updateProfileButtonV59==="function")updateProfileButtonV59(p);}catch(e){}
    try{if(typeof updateProfileButtonV61==="function")updateProfileButtonV61(p);}catch(e){}
    try{if(typeof tt102CompactUserButton==="function")tt102CompactUserButton();}catch(e){}
  }

  ensureUserProfile=function(showDialog){
    var now=Date.now();

    if(!showDialog){
      if(originalEnsure){
        try{return originalEnsure(false);}catch(e){}
      }
      return readProfile();
    }

    // Om en andra handler försöker starta samma Namn->Lag-flöde direkt efter första:
    // returnera bara den profil som nyss sparades.
    if(running || (now-lastCompletedAt<1800)){
      return lastProfile || readProfile();
    }

    running=true;
    try{
      var current=readProfile();

      // Kör egen enkel version, så vi kontrollerar exakt att det bara blir Namn sedan Lag.
      var name=window.prompt("Ditt namn",current&&current.ownerName?current.ownerName:"");
      if(name===null && current){
        lastProfile=current;
        return current;
      }

      var team=window.prompt("Lagkod / lagnamn",current&&current.teamCode?current.teamCode:"");
      if(team===null && current){
        lastProfile=current;
        return current;
      }

      lastProfile=saveProfileDirect(name,team);
      updateAllProfileButtons(lastProfile);
      return lastProfile;
    }finally{
      running=false;
      lastCompletedAt=Date.now();
      setTimeout(function(){lastCompletedAt=0;},2200);
    }
  };

  // Se till att äldre versionsfunktioner också använder samma låsta flöde.
  try{ensureProfileV59=function(showDialog){return ensureUserProfile(!!showDialog);};}catch(e){}
  try{ensureProfileV61=function(showDialog){return ensureUserProfile(!!showDialog);};}catch(e){}

  // Dämpa dubbelklick på profilknappar, utan att stoppa själva första klicket.
  function bindClickGuards(){
    ["btn-profile-team","btn-profile-v59","btn-profile-v61","tt102-profile-btn"].forEach(function(id){
      var b=document.getElementById(id);
      if(!b || b.dataset.tt155ClickGuard==="1")return;
      b.dataset.tt155ClickGuard="1";
      b.addEventListener("click",function(e){
        var now=Date.now();
        var last=Number(b.dataset.tt155LastClick||0);
        if(now-last<1200){
          e.preventDefault();
          e.stopPropagation();
          if(e.stopImmediatePropagation)e.stopImmediatePropagation();
          return false;
        }
        b.dataset.tt155LastClick=String(now);
      },true);
    });
  }

  setTimeout(bindClickGuards,300);
  setTimeout(bindClickGuards,1200);
  ["click","touchend"].forEach(function(evt){
    try{window.addEventListener(evt,function(){setTimeout(bindClickGuards,80);},false);}catch(e){}
  });
})();

/* === slut v155-user-profile-flow-lock === */


/* === v159-desktop-movement-safe: rörelsepil med mus utan att röra listor/render ===
   Bas: v155.
   Rör endast mousedown/mousemove/mouseup på pitch-svg i rörelseläge.
   Viktigt:
   - Ingen wrapper runt render().
   - Ingen ändring i taktiklistan.
   - Ingen ändring i delning/Mina/Lagets.
*/

(function(){
  if(window.__tt159DesktopMovementSafe)return;
  window.__tt159DesktopMovementSafe=true;

  function tt159CanDrawMovement(){
    try{
      if(typeof mode==="undefined" || mode!=="movement")return false;
      if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null){
        var tk=null;
        try{tk=(typeof tt145CurrentTk==="function")?tt145CurrentTk():null;}catch(e){}
        if(!tk){
          try{tk=(taktikFilmer||[])[editingTaktikIdx];}catch(e){}
        }
        try{if(typeof tt76IsReadOnly==="function" && tt76IsReadOnly(tk))return false;}catch(e){}
      }
      return true;
    }catch(e){return false;}
  }

  function tt159Dist(a,b){
    if(!a||!b)return 999999;
    var dx=(a.x||0)-(b.x||0);
    var dy=(a.y||0)-(b.y||0);
    return Math.sqrt(dx*dx+dy*dy);
  }

  function tt159NearestToken(pt){
    var best=null;

    try{
      (players||[]).forEach(function(p){
        var d=tt159Dist(pt,p);
        if(d<=24 && (!best || d<best.d)){
          best={id:p.id,x:p.x,y:p.y,d:d};
        }
      });
    }catch(e){}

    try{
      var bd=tt159Dist(pt,ball);
      if(bd<=24 && (!best || bd<best.d)){
        best={id:"ball",x:ball.x,y:ball.y,d:bd};
      }
    }catch(e){}

    return best;
  }

  function tt159IsDeleteOrExistingMovementTarget(target){
    try{
      if(!target || !target.closest)return false;
      if(target.closest(".mv-path-g"))return true;
      if(target.classList && (
        target.classList.contains("del-circ") ||
        target.classList.contains("del-txt")
      ))return true;
    }catch(e){}
    return false;
  }

  function tt159SaveAfterMovement(){
    setTimeout(function(){
      try{
        if(typeof tt145SaveCurrentStep==="function")tt145SaveCurrentStep({allowAutoCreate:false});
        else if(typeof tt76SaveCurrentStep==="function")tt76SaveCurrentStep({allowAutoCreate:false});
      }catch(e){}
    },70);
  }

  function tt159OnMouseDown(ev){
    if(ev.__tt159Handled)return;
    if(ev.button!==undefined && ev.button!==0)return;
    if(!tt159CanDrawMovement())return;

    var svg=document.getElementById("pitch-svg");
    if(!svg || !svg.contains(ev.target))return;
    if(tt159IsDeleteOrExistingMovementTarget(ev.target))return;

    var pt=null;
    try{pt=svgPt(ev.clientX,ev.clientY);}catch(e){return;}
    var token=tt159NearestToken(pt);
    if(!token)return;

    ev.__tt159Handled=true;
    ev.preventDefault();
    ev.stopPropagation();
    if(ev.stopImmediatePropagation)ev.stopImmediatePropagation();

    try{saveUndo();}catch(e){}

    movementCurrent={
      id:"mv"+(idCounter++),
      playerId:token.id,
      pts:[{x:token.x,y:token.y}]
    };

    function onMove(e2){
      if(!movementCurrent)return;
      e2.preventDefault();
      try{
        movementCurrent.pts.push(svgPt(e2.clientX,e2.clientY));
        if(typeof renderMovementPreview==="function")renderMovementPreview();
        else render();
      }catch(e){}
    }

    function onUp(e2){
      window.removeEventListener("mousemove",onMove,true);
      window.removeEventListener("mouseup",onUp,true);

      if(movementCurrent && movementCurrent.pts && movementCurrent.pts.length>3){
        try{
          if(typeof resamplePath==="function"){
            movementCurrent.pts=resamplePath(movementCurrent.pts,30);
          }
        }catch(e){}
        try{movementPaths.push(movementCurrent);}catch(e){}
      }

      movementCurrent=null;
      try{render();}catch(e){}
      tt159SaveAfterMovement();
    }

    window.addEventListener("mousemove",onMove,true);
    window.addEventListener("mouseup",onUp,true);
  }

  function tt159Bind(){
    var svg=document.getElementById("pitch-svg");
    if(!svg || svg.dataset.tt159MouseMovement==="1")return;
    svg.dataset.tt159MouseMovement="1";
    svg.addEventListener("mousedown",tt159OnMouseDown,true);
  }

  // Bind utan att wrappa render eller listfunktioner.
  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",function(){setTimeout(tt159Bind,200);});
  }else{
    setTimeout(tt159Bind,200);
  }

  // För säkerhets skull, om pitch-svg skapas sent när taktikfilm öppnas.
  // Detta pollar bara efter SVG:t, utan att påverka rendering/listor.
  var tries=0;
  var timer=setInterval(function(){
    tries++;
    tt159Bind();
    if(tries>40 || (document.getElementById("pitch-svg") && document.getElementById("pitch-svg").dataset.tt159MouseMovement==="1")){
      clearInterval(timer);
    }
  },250);

  ["click","touchend"].forEach(function(evt){
    try{
      window.addEventListener(evt,function(){
        setTimeout(tt159Bind,120);
      },false);
    }catch(e){}
  });
})();

/* === slut v159-desktop-movement-safe === */


/* === v176-taktik-filesystem-like-formations ===
   Bas: v175/v159.
   Mål: Låt Taktikfilm följa samma filsystemsmodell som fungerande Utgångsläge.
   Rör:
   - cloudSaveTaktik
   - cloudLoadTaktik
   - isMine/isVisible/isReadOnly för taktikfilm
   - patchTaktikShareV10
   - copyTaktikToMineV10 / duplicateTaktik
   Rör INTE:
   - taktikmotor
   - steglogik
   - spelarflytt
   - rörelsepilar
   - animation
   - fullscreen
   - renderTaktikList, förutom att den använder funktionerna ovan
*/

(function(){
  if(window.__tt176TaktikFilesystemLikeFormations)return;
  window.__tt176TaktikFilesystemLikeFormations=true;

  function clone(o){try{return JSON.parse(JSON.stringify(o));}catch(e){return o;}}
  function norm(v){return String(v||"").trim().toLowerCase();}
  function teamNorm(v){return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");}
  function isTaktik(obj){return !!(obj && Array.isArray(obj.steps));}
  function idOf(tk){return String((tk && (tk.dbId || tk.id)) || "").trim();}

  function profile(){
    try{if(typeof getUserProfile==="function"){var p=getUserProfile();if(p)return p;}}catch(e){}
    try{var raw=localStorage.getItem("tt_profile_v1");if(raw)return JSON.parse(raw);}catch(e){}
    return null;
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function hasOwnerMeta(tk){
    var m=meta(tk);
    return !!(m && (m.ownerId || m.ownerName || m.teamId || m.teamCode || m.teamName));
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function isMine(tk){
    if(!isTaktik(tk))return false;
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;

    // Nya/egna lokala utkast utan dbId men utan metadata ska vara mina.
    if(!idOf(tk) && !hasOwnerMeta(tk))return true;

    // Äldre lokala objekt som redan ligger i Mina-listan och inte har metadata får
    // betraktas som egna tills de sparas och får korrekt metadata.
    if(!hasOwnerMeta(tk)){
      try{
        if(typeof taktikScope==="undefined" || taktikScope==="mine"){
          return Array.isArray(taktikFilmer) && taktikFilmer.indexOf(tk)>=0;
        }
      }catch(e){}
      return false;
    }

    if(m.ownerId && p.ownerId && String(m.ownerId)===String(p.ownerId))return true;

    var sameName=!!(m.ownerName && p.ownerName && norm(m.ownerName)===norm(p.ownerName));
    if(sameName && sameTeam(tk))return true;

    return false;
  }

  function sharedToMyTeam(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function visible(tk,scope){
    return scope==="team" ? sharedToMyTeam(tk) : isMine(tk);
  }

  function readOnly(tk){
    try{
      if(typeof taktikScope!=="undefined" && taktikScope==="team" && sharedToMyTeam(tk))return true;
    }catch(e){}
    return !isMine(tk);
  }

  function ensureMeta(tk, opts){
    opts=opts||{};
    if(!isTaktik(tk))return tk;

    var p=profile();
    var m=clone(meta(tk)||{});

    if(p){
      m.ownerId=p.ownerId;
      m.ownerName=p.ownerName || "Tränare";
      m.teamId=p.teamId || p.teamCode || p.teamName || "MITT-LAG";
      m.teamCode=p.teamCode || p.teamId || p.teamName || "MITT-LAG";
      m.teamName=p.teamName || p.teamCode || p.teamId || "MITT-LAG";
    }

    if(typeof opts.sharedWithTeam==="boolean"){
      m.sharedWithTeam=!!opts.sharedWithTeam;
    }else{
      m.sharedWithTeam=!!m.sharedWithTeam;
    }

    m.teamCanEdit=false;
    m.kind="taktikfilm";
    m.schemaVersion=m.schemaVersion || 3;
    m.updatedAt=new Date().toISOString();
    if(!m.createdAt)m.createdAt=new Date().toISOString();

    tk._meta=m;
    tk.type="taktikfilm";
    tk.folder=tk.folder || "Taktik";
    tk.name=tk.name || "Taktikfilm";

    // Egna filer ska inte bära med sig skrivskyddsflaggor.
    delete tk._readOnly;
    delete tk._openedFromTeam;
    delete tk.readOnly;
    delete tk.readonly;
    delete tk._readonly;

    return tk;
  }

  function normalizeLoaded(row){
    var tk=clone((row && row.data) || {});
    if(!Array.isArray(tk.steps))tk.steps=[];
    tk.dbId=row.id;
    tk.id=row.id;
    tk.name=tk.name || row.name || "Taktikfilm";
    tk.folder=tk.folder || row.folder || "Taktik";
    tk.type="taktikfilm";
    if(tk._meta){
      tk._meta.kind=tk._meta.kind || "taktikfilm";
    }
    if(isMine(tk)){
      delete tk._readOnly;
      delete tk._openedFromTeam;
    }
    return tk;
  }

  function dedupe(list){
    var by={};
    (list||[]).forEach(function(tk){
      if(!tk)return;
      var key=tk.dbId ? "id:"+tk.dbId : "name:"+String(tk.name||"").trim().toLowerCase()+"|"+String(tk.folder||"Taktik");
      by[key]=tk;
    });
    return Object.keys(by).map(function(k){return by[k];});
  }

  function rebuildFolders(){
    try{
      var seen={};
      taktikFolders=["Taktik","Träning"];
      seen["Taktik"]=true;
      seen["Träning"]=true;
      (taktikFilmer||[]).forEach(function(tk){
        var f=tk.folder || "Taktik";
        if(f && !seen[f]){
          seen[f]=true;
          taktikFolders.push(f);
        }
      });
    }catch(e){}
  }

  function updateLocal(saved, original){
    if(!saved)return null;
    var target=null;
    try{
      if(original && Array.isArray(taktikFilmer)){
        target=taktikFilmer.find(function(x){return x===original;}) || null;
      }
      if(!target && saved.dbId && Array.isArray(taktikFilmer)){
        target=taktikFilmer.find(function(x){return x.dbId && String(x.dbId)===String(saved.dbId);}) || null;
      }
      if(target){
        Object.keys(target).forEach(function(k){delete target[k];});
        Object.keys(saved).forEach(function(k){target[k]=saved[k];});
        return target;
      }
      taktikFilmer.unshift(saved);
      return saved;
    }catch(e){
      return saved;
    }
  }

  // Globala behörighetsfunktioner som renderTaktikList redan använder.
  var oldIsMineV10 = (typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return isMine(obj);
    return oldIsMineV10 ? oldIsMineV10(obj) : true;
  };

  var oldTeamSharedV10 = (typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return sharedToMyTeam(obj);
    return oldTeamSharedV10 ? oldTeamSharedV10(obj) : false;
  };

  var oldVisibleV10 = (typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return visible(obj,scope);
    return oldVisibleV10 ? oldVisibleV10(obj,scope) : true;
  };

  var oldReadOnlyV10 = (typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj))return readOnly(obj);
    return oldReadOnlyV10 ? oldReadOnlyV10(obj) : false;
  };

  // Save enligt samma idé som Utgångsläge: data innehåller metadata.
  cloudSaveTaktik=function(tk){
    if(!tk){
      try{
        if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null && taktikFilmer && taktikFilmer[editingTaktikIdx]){
          tk=taktikFilmer[editingTaktikIdx];
        }
      }catch(e){}
      try{if(!tk && playback && playback.tk)tk=playback.tk;}catch(e){}
    }

    if(!isTaktik(tk)){
      showToast("Ingen taktikfilm att spara",false);
      return Promise.resolve(null);
    }

    if(readOnly(tk)){
      showToast("Filen är skrivskyddad. Kopiera den först.",false);
      return Promise.resolve(null);
    }

    try{
      if(typeof tt145SaveCurrentStep==="function"){
        tt145SaveCurrentStep({allowAutoCreate:false});
      }
    }catch(e){}

    if(!tk.steps || tk.steps.length<2){
      showToast("Lägg till minst ett steg innan du sparar filmen",false);
      try{cloudStatus("⚠️ Minst ett steg krävs för att spara taktikfilm","#e8c84a");}catch(e){}
      return Promise.resolve(null);
    }

    ensureMeta(tk, {sharedWithTeam: !!meta(tk).sharedWithTeam});

    var id=idOf(tk);
    var url=id
      ? SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?id=eq."+id
      : SUPA_URL+"/rest/v1/"+SUPA_TABLE;
    var method=id ? "PATCH" : "POST";

    var payload={
      name:tk.name || "Taktikfilm",
      data:tk,
      type:"taktikfilm",
      folder:tk.folder || "Taktik"
    };

    try{cloudStatus("Sparar taktik...","#7aaa88");}catch(e){}

    return fetch(url,{
      method:method,
      headers:Object.assign({},supaHeaders(),{"Prefer":"return=representation"}),
      body:JSON.stringify(payload)
    })
    .then(function(r){
      if(!r.ok)throw new Error("HTTP "+r.status);
      return r.json();
    })
    .then(function(rows){
      var saved=clone(tk);
      if(rows && rows[0] && rows[0].id){
        saved.dbId=rows[0].id;
        saved.id=rows[0].id;
      }else if(id){
        saved.dbId=id;
        saved.id=id;
      }

      ensureMeta(saved, {sharedWithTeam: !!meta(saved).sharedWithTeam});
      var local=updateLocal(saved, tk);

      try{
        if(playback && playback.tk && (playback.tk===tk || idOf(playback.tk)===idOf(local))){
          playback.tk=local;
        }
      }catch(e){}

      try{taktikScope="mine";currentTaktikFolder="Alla";}catch(e){}
      rebuildFolders();
      try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}
      try{cloudStatus("✅ Film sparad: "+(local.name||"Taktikfilm"),"#4ae87a");}catch(e){}
      try{showToast("Film sparad!");}catch(e){}
      try{if(typeof markTaktikSavedCleanV67==="function")markTaktikSavedCleanV67(local);}catch(e){}

      return local;
    })
    .catch(function(err){
      try{cloudStatus("❌ Kunde inte spara taktik: "+err.message,"#e84a4a");}catch(e){}
      try{showToast("Kunde inte spara taktik",false);}catch(e){}
      throw err;
    });
  };

  // Load efter Utgångsläge-modell: hämta alla, välj taktikrader, filtrera lokalt.
  cloudLoadTaktik=function(){
    try{cloudStatus("Laddar taktik...","#7aaa88");}catch(e){}

    return fetch(SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?order=id.desc",{headers:supaHeaders()})
      .then(function(r){
        if(!r.ok)throw new Error("HTTP "+r.status);
        return r.json();
      })
      .then(function(rows){
        if(!Array.isArray(rows))rows=[];

        var loaded=[];
        rows.forEach(function(row){
          var data=row && row.data;
          var isRowTaktik=(row && row.type==="taktikfilm") || (data && Array.isArray(data.steps));
          if(!isRowTaktik)return;

          var tk=normalizeLoaded(row);
          if(!tk.steps || tk.steps.length<2)return;

          if(isMine(tk) || sharedToMyTeam(tk)){
            loaded.push(tk);
          }
        });

        taktikFilmer=dedupe(loaded);
        rebuildFolders();

        try{
          if(typeof currentTaktikFolder==="undefined" || !currentTaktikFolder)currentTaktikFolder="Alla";
          if(typeof taktikScope==="undefined" || !taktikScope)taktikScope="mine";
        }catch(e){}

        try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}
        try{
          var mineCount=taktikFilmer.filter(function(tk){return isMine(tk);}).length;
          var teamCount=taktikFilmer.filter(function(tk){return sharedToMyTeam(tk);}).length;
          cloudStatus("✅ Taktik laddad: Mina "+mineCount+" · Lagets "+teamCount,"#4ae87a");
        }catch(e){
          cloudStatus("✅ Taktik laddad","#4ae87a");
        }
      })
      .catch(function(err){
        try{cloudStatus("❌ Kunde inte ladda taktik: "+err.message,"#e84a4a");}catch(e){}
      });
  };

  patchTaktikShareV10=function(tk,share){
    if(!isTaktik(tk)){
      showToast("Ingen film vald",false);
      return;
    }

    if(typeof taktikScope!=="undefined" && taktikScope==="team"){
      showToast("Delning ändras från Mina, inte från Lagets",false);
      return;
    }

    if(!idOf(tk)){
      showToast("Spara filmen innan du delar den",false);
      return;
    }

    // Följ Utgångsläge: om filen ligger i Mina tillåter vi delningsklicket att reparera metadata.
    var canPatch=isMine(tk);
    if(!canPatch){
      try{
        canPatch=(typeof taktikScope==="undefined" || taktikScope==="mine") &&
          Array.isArray(taktikFilmer) &&
          taktikFilmer.some(function(x){return String(idOf(x))===String(idOf(tk));});
      }catch(e){}
    }

    if(!canPatch){
      showToast("Du kan inte ändra delning på någon annans fil",false);
      return;
    }

    ensureMeta(tk,{sharedWithTeam:!!share});

    try{taktikScope="mine";currentTaktikFolder="Alla";}catch(e){}
    try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}

    try{cloudStatus(share?"Delar film med laget...":"Tar bort delning...","#7aaa88");}catch(e){}

    fetch(SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?id=eq."+idOf(tk),{
      method:"PATCH",
      headers:Object.assign({},supaHeaders(),{"Prefer":"return=representation"}),
      body:JSON.stringify({
        name:tk.name || "Taktikfilm",
        data:tk,
        type:"taktikfilm",
        folder:tk.folder || "Taktik"
      })
    })
    .then(function(r){
      if(!r.ok)throw new Error("HTTP "+r.status);
      return r.json();
    })
    .then(function(){
      showToast(share?"Film delad med laget":"Film inte längre delad");
      try{cloudStatus(share?"✅ Delad med laget":"✅ Delning borttagen","#4ae87a");}catch(e){}
      setTimeout(function(){try{cloudLoadTaktik();}catch(e){}},350);
    })
    .catch(function(err){
      showToast("Kunde inte ändra delning",false);
      try{cloudStatus("❌ "+err.message,"#e84a4a");}catch(e){}
    });
  };

  copyTaktikToMineV10=function(tk){
    if(!isTaktik(tk))return;

    var copy=clone(tk);
    delete copy.dbId;
    delete copy.id;
    delete copy._readOnly;
    delete copy._openedFromTeam;
    delete copy.readOnly;
    delete copy.readonly;
    delete copy._readonly;
    delete copy._draftUid;

    copy.name="Kopia av "+(tk.name || "Taktikfilm");
    copy.folder=copy.folder || "Taktik";
    ensureMeta(copy,{sharedWithTeam:false});

    try{
      taktikFilmer.unshift(copy);
      taktikScope="mine";
      currentTaktikFolder="Alla";
      rebuildFolders();
      if(typeof renderTaktikList==="function")renderTaktikList();
    }catch(e){}

    cloudSaveTaktik(copy);
  };

  duplicateTaktik=function(idx){
    try{copyTaktikToMineV10((taktikFilmer||[])[idx]);}catch(e){}
  };

  // Minimal skydd för editorn: om renderTaktikList öppnar från Mina ska den inte ärva skrivskydd.
  function makeMineEditable(tk){
    if(!isTaktik(tk) || !isMine(tk))return tk;
    delete tk._readOnly;
    delete tk._openedFromTeam;
    delete tk.readOnly;
    delete tk.readonly;
    delete tk._readonly;
    return tk;
  }

  if(typeof startPlayback==="function" && !startPlayback._tt176Wrapped){
    var oldStart=startPlayback;
    startPlayback=function(idx){
      try{
        var tk=(taktikFilmer||[])[idx];
        if(tk && (typeof taktikScope==="undefined" || taktikScope==="mine"))makeMineEditable(tk);
      }catch(e){}
      var r=oldStart.apply(this,arguments);
      try{
        var tk2=(taktikFilmer||[])[idx];
        if(tk2 && (typeof taktikScope==="undefined" || taktikScope==="mine")){
          makeMineEditable(tk2);
          if(playback && playback.tk)makeMineEditable(playback.tk);
        }
      }catch(e){}
      return r;
    };
    startPlayback._tt176Wrapped=true;
  }

  try{
    if(typeof renderTaktikList==="function")renderTaktikList();
  }catch(e){}

  window.tt176TaktikFs={
    isMine:isMine,
    sharedToMyTeam:sharedToMyTeam,
    visible:visible,
    readOnly:readOnly,
    ensureMeta:ensureMeta
  };
})();

/* === slut v176-taktik-filesystem-like-formations === */


/* === v177-editor-save-uses-cloudSaveTaktik ===
   Bas: v176.
   Konkret fel:
   - Gamla editorns spara-knappar går förbi cloudSaveTaktik.
   - För ny film utan dbId visar de bara "Sparad lokalt".
   - Då försvinner filmen efter refresh.
   Fix:
   - Fånga editorns save-klick i capture phase.
   - Stoppa gamla handlern.
   - Kör alltid cloudSaveTaktik(tk).
   Rör INTE redigering, drag/drop, animation, render eller filsystem i övrigt.
*/

(function(){
  if(window.__tt177EditorSaveUsesCloudSaveTaktik)return;
  window.__tt177EditorSaveUsesCloudSaveTaktik=true;

  function currentTaktik(){
    try{
      if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null && Array.isArray(taktikFilmer) && taktikFilmer[editingTaktikIdx]){
        return taktikFilmer[editingTaktikIdx];
      }
    }catch(e){}
    try{
      if(playback && playback.tk && Array.isArray(playback.tk.steps)){
        return playback.tk;
      }
    }catch(e){}
    return null;
  }

  function syncCurrentStep(){
    try{
      if(typeof tt145SaveCurrentStep==="function"){
        tt145SaveCurrentStep({allowAutoCreate:false});
        return;
      }
    }catch(e){}
    try{
      if(typeof tt76SaveCurrentStep==="function"){
        tt76SaveCurrentStep({allowAutoCreate:false});
        return;
      }
    }catch(e){}
  }

  function saveViaCloudButton(e){
    var btn=e.target && e.target.closest ? e.target.closest("#btn-edit-taktik-save,#btn-taktikbar-save") : null;
    if(!btn)return;

    var tk=currentTaktik();
    if(!tk || !Array.isArray(tk.steps))return;

    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation)e.stopImmediatePropagation();

    syncCurrentStep();

    tk=currentTaktik() || tk;

    if(!tk.steps || tk.steps.length<2){
      try{showToast("Lägg till minst ett steg innan du sparar filmen",false);}catch(err){}
      try{cloudStatus("⚠️ Minst ett steg krävs för att spara taktikfilm","#e8c84a");}catch(err){}
      return false;
    }

    try{
      if(typeof cloudSaveTaktik==="function"){
        cloudSaveTaktik(tk);
      }else{
        showToast("Kunde inte hitta molnsparning",false);
      }
    }catch(err){
      try{showToast("Kunde inte spara film",false);}catch(e2){}
      try{cloudStatus("❌ "+err.message,"#e84a4a");}catch(e2){}
    }

    return false;
  }

  document.addEventListener("click",saveViaCloudButton,true);

  // Metamodalen har också en gammal handler som PATCH:ar/lokalsparar direkt.
  // Här låter vi den först uppdatera namn/mapp i objektet och sparar sedan via cloudSaveTaktik.
  document.addEventListener("click",function(e){
    var btn=e.target && e.target.closest ? e.target.closest("#edit-taktik-ok") : null;
    if(!btn)return;

    var tk=currentTaktik();
    if(!tk || !Array.isArray(tk.steps))return;

    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation)e.stopImmediatePropagation();

    try{
      var nameInp=document.getElementById("edit-taktik-name-inp");
      var folderSel=document.getElementById("edit-taktik-folder");
      if(nameInp)tk.name=nameInp.value.trim() || tk.name;
      if(folderSel)tk.folder=folderSel.value || tk.folder || "Taktik";
      var title=document.getElementById("edit-taktik-title-lbl");
      if(title)title.textContent="✏ "+tk.name;
      var modal=document.getElementById("modal-edit-taktik-meta");
      if(modal)modal.classList.add("hidden");
    }catch(err){}

    syncCurrentStep();

    try{
      if(typeof cloudSaveTaktik==="function")cloudSaveTaktik(tk);
    }catch(err){
      try{showToast("Kunde inte spara film",false);}catch(e2){}
      try{cloudStatus("❌ "+err.message,"#e84a4a");}catch(e2){}
    }

    return false;
  },true);
})();

/* === slut v177-editor-save-uses-cloudSaveTaktik === */


/* === v178-save-clears-warning ===
   Bas: v177.
   v177 fixade att editor-spara verkligen går via cloudSaveTaktik och filen finns kvar efter refresh.
   Kvar: appen visar osparat-varning trots lyckad sparning.
   Fix:
   - efter lyckad cloudSaveTaktik nollställs dirty/snapshot-flaggor.
   Rör inte save/load/redigering i övrigt.
*/

(function(){
  if(window.__tt178SaveClearsWarning)return;
  window.__tt178SaveClearsWarning=true;

  function currentTaktik(){
    try{
      if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null && Array.isArray(taktikFilmer) && taktikFilmer[editingTaktikIdx]){
        return taktikFilmer[editingTaktikIdx];
      }
    }catch(e){}
    try{if(playback && playback.tk && Array.isArray(playback.tk.steps))return playback.tk;}catch(e){}
    return null;
  }

  function cloneClean(obj){
    try{
      var x=JSON.parse(JSON.stringify(obj||{}));
      delete x._readOnly;
      delete x._openedFromTeam;
      delete x._forceEditableV171;
      delete x._openedFromMineV171;
      delete x._forceEditableV170;
      return x;
    }catch(e){
      return obj;
    }
  }

  function clearDirty(tk){
    tk=tk || currentTaktik();
    if(!tk)return;

    try{ if(typeof markTaktikSavedCleanV67==="function") markTaktikSavedCleanV67(tk); }catch(e){}
    try{ if(typeof tt67MarkSavedClean==="function") tt67MarkSavedClean(tk); }catch(e){}
    try{ if(typeof markTaktikSavedClean==="function") markTaktikSavedClean(tk); }catch(e){}
    try{ if(typeof tt23MarkTaktikClean==="function") tt23MarkTaktikClean(tk); }catch(e){}

    try{ taktikDirtyV17=false; }catch(e){}
    try{ window.taktikDirtyV17=false; }catch(e){}
    try{ dirtyTaktikV17=false; }catch(e){}
    try{ window.dirtyTaktikV17=false; }catch(e){}
    try{ taktikHasUnsavedChanges=false; }catch(e){}
    try{ window.taktikHasUnsavedChanges=false; }catch(e){}
    try{ hasUnsavedTaktikChanges=false; }catch(e){}
    try{ window.hasUnsavedTaktikChanges=false; }catch(e){}
    try{ unsavedTaktikChanges=false; }catch(e){}
    try{ window.unsavedTaktikChanges=false; }catch(e){}
    try{ editTaktikDirty=false; }catch(e){}
    try{ window.editTaktikDirty=false; }catch(e){}

    // Några versioner jämför mot snapshot. Sätt snapshot efter sparning.
    try{ savedTaktikSnapshotV17=JSON.stringify(cloneClean(tk)); }catch(e){}
    try{ window.savedTaktikSnapshotV17=JSON.stringify(cloneClean(tk)); }catch(e){}
    try{ lastSavedTaktikSnapshot=JSON.stringify(cloneClean(tk)); }catch(e){}
    try{ window.lastSavedTaktikSnapshot=JSON.stringify(cloneClean(tk)); }catch(e){}
    try{ taktikSavedSnapshot=JSON.stringify(cloneClean(tk)); }catch(e){}
    try{ window.taktikSavedSnapshot=JSON.stringify(cloneClean(tk)); }catch(e){}

    // Statusrad/klass kan annars ligga kvar visuellt.
    try{ document.body.classList.remove("taktik-dirty"); }catch(e){}
    try{ document.body.classList.remove("has-unsaved-taktik"); }catch(e){}
  }

  if(typeof cloudSaveTaktik==="function" && !cloudSaveTaktik._tt178ClearWarningWrapped){
    var oldSave=cloudSaveTaktik;
    cloudSaveTaktik=function(){
      var ret=oldSave.apply(this,arguments);

      try{
        if(ret && typeof ret.then==="function"){
          return ret.then(function(saved){
            clearDirty(saved || currentTaktik());
            setTimeout(function(){ clearDirty(saved || currentTaktik()); },0);
            setTimeout(function(){ clearDirty(saved || currentTaktik()); },250);
            return saved;
          });
        }
      }catch(e){}

      setTimeout(function(){ clearDirty(currentTaktik()); },0);
      return ret;
    };
    cloudSaveTaktik._tt178ClearWarningWrapped=true;
  }

  // Om v177:s klickfångare sparar och gammal UI-kod hinner sätta dirty efteråt,
  // rensa ännu en gång strax efter spara-klicket.
  document.addEventListener("click",function(e){
    var btn=e.target && e.target.closest ? e.target.closest("#btn-edit-taktik-save,#btn-taktikbar-save,#edit-taktik-ok") : null;
    if(!btn)return;
    setTimeout(function(){ clearDirty(currentTaktik()); },600);
    setTimeout(function(){ clearDirty(currentTaktik()); },1200);
  },true);

  window.tt178ClearTaktikDirty=function(){ clearDirty(currentTaktik()); };
})();

/* === slut v178-save-clears-warning === */


/* === v179-unified-unsaved-after-cloud-save ===
   Bas: v178.
   v177 fixade verklig molnsparning.
   v178 rensade några dirty-flaggor, men gamla snapshot-lager kan fortfarande varna.
   v179 gör bara detta:
   - en gemensam osparat-kontroll för taktikfilm
   - efter lyckad molnsparning tas ny snapshot
   - metadata/id ignoreras vid jämförelse
   Rör inte save/load/redigering/delning/kopiering.
*/

(function(){
  if(window.__tt179UnifiedUnsavedAfterCloudSave)return;
  window.__tt179UnifiedUnsavedAfterCloudSave=true;

  var tt179Snapshot="";
  var tt179LastCleanAt=0;

  function currentTaktik(){
    try{
      if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null && Array.isArray(taktikFilmer) && taktikFilmer[editingTaktikIdx]){
        return taktikFilmer[editingTaktikIdx];
      }
    }catch(e){}
    try{
      if(playback && playback.tk && Array.isArray(playback.tk.steps))return playback.tk;
    }catch(e){}
    return null;
  }

  function saveCurrentStepQuiet(){
    try{
      if(typeof tt76SaveCurrentStep==="function"){
        tt76SaveCurrentStep({allowAutoCreate:false});
        return;
      }
    }catch(e){}
    try{
      if(typeof saveCurrentStepV75==="function"){
        saveCurrentStepV75({allowAutoCreate:false});
        return;
      }
    }catch(e){}
    try{
      if(typeof autoSaveCurrentStepLocalV16==="function"){
        autoSaveCurrentStepLocalV16();
        return;
      }
    }catch(e){}
  }

  function normalized(tk){
    try{
      var c=JSON.parse(JSON.stringify(tk||{}));

      // Använd befintlig normalisering om den finns, men håll vår egen städning efteråt.
      try{
        if(typeof tt76NormalizeFilm==="function"){
          c=tt76NormalizeFilm(c) || c;
        }
      }catch(e){}

      // Dessa kan ändras av molnsparning, delning eller öppning utan att filmen i sig ändrats.
      delete c.dbId;
      delete c.id;
      delete c._meta;
      delete c.meta;
      delete c._readOnly;
      delete c._openedFromTeam;
      delete c.readOnly;
      delete c.readonly;
      delete c._readonly;
      delete c._isDraft;
      delete c._draftUid;
      delete c._forceEditableV170;
      delete c._forceEditableV171;
      delete c._openedFromMineV171;
      delete c._localBackupV173;
      delete c._localBackupV174;
      delete c._localBackupUpdatedAtV173;
      delete c._localBackupUpdatedAtV174;
      delete c._restoredFromLocalBackupV173;
      delete c._restoredFromLocalBackupV174;
      delete c._saving;
      delete c._dirty;

      return JSON.stringify(c);
    }catch(e){
      return "";
    }
  }

  function forceClean(tk){
    tk=tk || currentTaktik();
    if(!tk)return;

    // Få in aktuellt steg innan snapshot tas.
    saveCurrentStepQuiet();
    tk=currentTaktik() || tk;

    tt179Snapshot=normalized(tk);
    tt179LastCleanAt=Date.now();

    // Nollställ gamla lager också, så gamla listeners inte ligger kvar visuellt/logiskt.
    try{taktikDirtyV17=false;}catch(e){}
    try{window.taktikDirtyV17=false;}catch(e){}
    try{dirtyTaktikV17=false;}catch(e){}
    try{window.dirtyTaktikV17=false;}catch(e){}
    try{taktikHasUnsavedChanges=false;}catch(e){}
    try{window.taktikHasUnsavedChanges=false;}catch(e){}
    try{hasUnsavedTaktikChanges=false;}catch(e){}
    try{window.hasUnsavedTaktikChanges=false;}catch(e){}
    try{unsavedTaktikChanges=false;}catch(e){}
    try{window.unsavedTaktikChanges=false;}catch(e){}
    try{editTaktikDirty=false;}catch(e){}
    try{window.editTaktikDirty=false;}catch(e){}

    try{lastTaktikSaveAtV23=Date.now();}catch(e){}
    try{v74LastSaveAt=Date.now();}catch(e){}

    try{
      if(typeof tt88SavedSnapshot!=="undefined")tt88SavedSnapshot=tt179Snapshot;
      if(typeof tt88DirtyAfterSave!=="undefined")tt88DirtyAfterSave=false;
      if(typeof tt88SavingNow!=="undefined")tt88SavingNow=false;
    }catch(e){}

    try{
      if(typeof ttV76!=="undefined" && ttV76){
        ttV76.savedSnapshot=tt179Snapshot;
        ttV76.lastSaveAt=Date.now();
        ttV76.suppressDirty=false;
      }
    }catch(e){}

    try{savedTaktikSnapshotV21=tt179Snapshot;}catch(e){}
    try{window.savedTaktikSnapshotV21=tt179Snapshot;}catch(e){}

    try{if(typeof markTaktikSavedCleanV67==="function")markTaktikSavedCleanV67(tk);}catch(e){}
    try{if(typeof tt76ForceClean==="function")tt76ForceClean(tk);}catch(e){}
    try{if(typeof tt86MarkCleanNow==="function")tt86MarkCleanNow(tk);}catch(e){}
    try{if(typeof tt88CaptureSavedSnapshot==="function")tt88CaptureSavedSnapshot();}catch(e){}

    // Efter anrop till äldre clean-funktioner kan deras normalisering ha satt eget snapshot.
    // Sätt vår snapshot sist igen.
    try{savedTaktikSnapshotV21=tt179Snapshot;}catch(e){}
    try{if(typeof tt88SavedSnapshot!=="undefined")tt88SavedSnapshot=tt179Snapshot;}catch(e){}
    try{if(typeof tt88DirtyAfterSave!=="undefined")tt88DirtyAfterSave=false;}catch(e){}

    try{document.body.classList.remove("taktik-dirty");}catch(e){}
    try{document.body.classList.remove("has-unsaved-taktik");}catch(e){}
  }

  function hasUnsaved(){
    var tk=currentTaktik();
    if(!tk)return false;

    // Direkt efter save ska gamla mouseup/click-events inte hinna skapa falsk varning.
    if(Date.now()-tt179LastCleanAt<2500)return false;

    try{
      if(typeof tt76IsReadOnly==="function" && tt76IsReadOnly(tk))return false;
    }catch(e){}

    saveCurrentStepQuiet();
    tk=currentTaktik() || tk;

    var now=normalized(tk);
    if(!tt179Snapshot){
      tt179Snapshot=now;
      return false;
    }

    return now!==tt179Snapshot;
  }

  function confirmClean(){
    if(!hasUnsaved())return true;
    return confirm("Du har osparade ändringar i taktiken. Vill du lämna utan att spara?");
  }

  // Peka om alla kända varningsfunktioner till samma beslut.
  hasUnsavedTaktikChangesV21=hasUnsaved;
  hasUnsavedTaktikChangesV23=hasUnsaved;
  confirmUnsavedV21=confirmClean;
  confirmUnsavedV19=confirmClean;
  confirmUnsavedTaktikV18=confirmClean;
  confirmDiscardUnsavedV17=confirmClean;
  confirmUnsavedUnifiedV23=confirmClean;

  if(typeof cloudSaveTaktik==="function" && !cloudSaveTaktik._tt179CleanWrapped){
    var oldSave=cloudSaveTaktik;
    cloudSaveTaktik=function(){
      var ret=oldSave.apply(this,arguments);

      try{
        if(ret && typeof ret.then==="function"){
          return ret.then(function(saved){
            forceClean(saved || currentTaktik());
            setTimeout(function(){forceClean(saved || currentTaktik());},80);
            setTimeout(function(){forceClean(saved || currentTaktik());},500);
            return saved;
          });
        }
      }catch(e){}

      setTimeout(function(){forceClean(currentTaktik());},80);
      return ret;
    };
    cloudSaveTaktik._tt179CleanWrapped=true;
  }

  // När en film öppnas sätts en ny baslinje.
  if(typeof startPlayback==="function" && !startPlayback._tt179OpenWrapped){
    var oldStart=startPlayback;
    startPlayback=function(){
      var r=oldStart.apply(this,arguments);
      setTimeout(function(){forceClean(currentTaktik());},350);
      return r;
    };
    startPlayback._tt179OpenWrapped=true;
  }

  if(typeof openEditTaktik==="function" && !openEditTaktik._tt179OpenWrapped){
    var oldOpen=openEditTaktik;
    openEditTaktik=function(){
      var r=oldOpen.apply(this,arguments);
      setTimeout(function(){forceClean(currentTaktik());},350);
      return r;
    };
    openEditTaktik._tt179OpenWrapped=true;
  }

  // Extra säkerhet efter spara-klick, eftersom gamla click/mouseup-listeners kan sätta dirty efteråt.
  document.addEventListener("click",function(e){
    var btn=e.target && e.target.closest ? e.target.closest("#btn-edit-taktik-save,#btn-taktikbar-save,#edit-taktik-ok") : null;
    if(!btn)return;
    setTimeout(function(){forceClean(currentTaktik());},700);
    setTimeout(function(){forceClean(currentTaktik());},1400);
  },true);

  window.tt179ForceCleanTaktik=function(){forceClean(currentTaktik());};
  window.tt179HasUnsavedTaktik=hasUnsaved;
})();

/* === slut v179-unified-unsaved-after-cloud-save === */


/* === v180-strict-mine-owner ===
   Bas: 179.
   Fel: sparade taktikfilmer kunde synas i Mina för annan användare i samma lag.
   Orsak: ägarfallback från felsökningen var för generös.
   Fix:
   - Mina för sparade taktikfilmer kräver ownerId === aktuell ownerId.
   - Endast helt nya osparade lokala utkast utan id/dbId får räknas som mina utan ownerId.
   - Lagets fortsätter visa sharedWithTeam=true i samma lag.
   Rör inte redigering, spara, osparat-varning, delning eller kopiering.
*/

(function(){
  if(window.__tt180StrictMineOwner)return;
  window.__tt180StrictMineOwner=true;

  function isTaktik(obj){
    return !!(obj && Array.isArray(obj.steps));
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function profile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      if(raw)return JSON.parse(raw);
    }catch(e){}
    return null;
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function teamNorm(v){
    return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function strictMine(tk){
    if(!isTaktik(tk))return false;

    var id=idOf(tk);
    var m=meta(tk);
    var p=profile();

    // Bara helt nya lokala utkast utan id får räknas som mina utan ownerId.
    // Så fort filen är sparad måste ownerId finnas och matcha.
    if(!id && !(m && m.ownerId)){
      return true;
    }

    if(!p || !p.ownerId || !m || !m.ownerId){
      return false;
    }

    return String(m.ownerId)===String(p.ownerId);
  }

  function teamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  // Override bara behörighets-/filterfunktionerna för taktikfilm.
  var oldIsMineV10 = (typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return strictMine(obj);
    return oldIsMineV10 ? oldIsMineV10(obj) : true;
  };

  var oldTeamSharedV10 = (typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return teamShared(obj);
    return oldTeamSharedV10 ? oldTeamSharedV10(obj) : false;
  };

  var oldVisibleV10 = (typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj)){
      return scope==="team" ? teamShared(obj) : strictMine(obj);
    }
    return oldVisibleV10 ? oldVisibleV10(obj,scope) : true;
  };

  var oldReadOnlyV10 = (typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj)){
      try{
        if(typeof taktikScope!=="undefined" && taktikScope==="team" && teamShared(obj))return true;
      }catch(e){}
      return !strictMine(obj);
    }
    return oldReadOnlyV10 ? oldReadOnlyV10(obj) : false;
  };

  // v176/v179 exponerade ett hjälpbibliotek. Uppdatera det också så senare kod får samma regel.
  try{
    if(window.tt176TaktikFs){
      window.tt176TaktikFs.isMine=strictMine;
      window.tt176TaktikFs.sharedToMyTeam=teamShared;
      window.tt176TaktikFs.visible=function(tk,scope){return scope==="team" ? teamShared(tk) : strictMine(tk);};
      window.tt176TaktikFs.readOnly=function(tk){
        try{
          if(typeof taktikScope!=="undefined" && taktikScope==="team" && teamShared(tk))return true;
        }catch(e){}
        return !strictMine(tk);
      };
    }
  }catch(e){}

  // Ladda om listan med strikt Mina-filter när patchen aktiveras.
  try{
    if(typeof cloudLoadTaktik==="function"){
      cloudLoadTaktik();
    }else if(typeof renderTaktikList==="function"){
      renderTaktikList();
    }
  }catch(e){}

  window.tt180StrictMineTaktik=strictMine;
})();

/* === slut v180-strict-mine-owner === */


/* === v181-strict-mine-owner-name ===
   Bas: 180.
   Fel: filer syntes i Mina hos både person 1 och person 2.
   Slutsats: ownerId är inte tillräckligt personbundet i appens profilflöde.
   Fix:
   - Sparade taktikfilmer i Mina kräver personmatchning.
   - I första hand: ownerId + ownerName matchar.
   - För äldre filer utan ownerId: ownerName + team matchar.
   - Delade filer för annan person visas bara i Lagets, inte i Mina.
   - Filtrerar både i render-helper och efter cloudLoadTaktik.
   Rör bara app.js.
*/

(function(){
  if(window.__tt181StrictMineOwnerName)return;
  window.__tt181StrictMineOwnerName=true;

  function isTaktik(obj){
    return !!(obj && Array.isArray(obj.steps));
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function norm(v){
    return String(v||"").trim().toLowerCase();
  }

  function teamNorm(v){
    return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");
  }

  function profile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      if(raw)return JSON.parse(raw);
    }catch(e){}
    return null;
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function sameName(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && norm(p.ownerName) && norm(m.ownerName) && norm(p.ownerName)===norm(m.ownerName));
  }

  function sameOwnerId(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && p.ownerId && m.ownerId && String(p.ownerId)===String(m.ownerId));
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function hasOwnerMeta(tk){
    var m=meta(tk);
    return !!(m && (m.ownerId || m.ownerName));
  }

  function strictMine(tk){
    if(!isTaktik(tk))return false;

    var saved=!!idOf(tk);
    var m=meta(tk);

    // Helt nya lokala utkast utan id får räknas som egna tills de sparas.
    if(!saved && !hasOwnerMeta(tk))return true;

    // Sparade filer utan namn ska inte visas som Mina för alla.
    if(saved && !m.ownerName)return false;

    // Normal ny fil: kräv både id-match och namnmatch.
    if(m.ownerId){
      return sameOwnerId(tk) && sameName(tk);
    }

    // Äldre/migrerad fil utan ownerId: tillåt bara namn + lag.
    return sameName(tk) && sameTeam(tk);
  }

  function teamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function visible(tk,scope){
    return scope==="team" ? teamShared(tk) : strictMine(tk);
  }

  function readOnly(tk){
    try{
      if(typeof taktikScope!=="undefined" && taktikScope==="team" && teamShared(tk))return true;
    }catch(e){}
    return !strictMine(tk);
  }

  function filterCurrentList(){
    try{
      if(!Array.isArray(taktikFilmer))return;
      var scope=(typeof taktikScope!=="undefined" && taktikScope==="team") ? "team" : "mine";
      // Behåll båda typerna i minnet för flikar, men ta bort filer som varken är egna eller lagdelade.
      taktikFilmer=taktikFilmer.filter(function(tk){
        return strictMine(tk) || teamShared(tk);
      });
      try{
        if(typeof renderTaktikList==="function")renderTaktikList();
      }catch(e){}
    }catch(e){}
  }

  // Override globala helpers.
  var oldIsMineV10=(typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return strictMine(obj);
    return oldIsMineV10 ? oldIsMineV10(obj) : true;
  };

  var oldTeamSharedV10=(typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return teamShared(obj);
    return oldTeamSharedV10 ? oldTeamSharedV10(obj) : false;
  };

  var oldVisibleV10=(typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return visible(obj,scope);
    return oldVisibleV10 ? oldVisibleV10(obj,scope) : true;
  };

  var oldReadOnlyV10=(typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj))return readOnly(obj);
    return oldReadOnlyV10 ? oldReadOnlyV10(obj) : false;
  };

  try{
    if(window.tt176TaktikFs){
      window.tt176TaktikFs.isMine=strictMine;
      window.tt176TaktikFs.sharedToMyTeam=teamShared;
      window.tt176TaktikFs.visible=visible;
      window.tt176TaktikFs.readOnly=readOnly;
    }
  }catch(e){}

  // Viktigt: v176:s cloudLoadTaktik hade egen intern fallback.
  // Därför efterfiltrerar vi resultatet efter varje laddning.
  if(typeof cloudLoadTaktik==="function" && !cloudLoadTaktik._tt181StrictFilterWrapped){
    var oldLoad=cloudLoadTaktik;
    cloudLoadTaktik=function(){
      var ret=oldLoad.apply(this,arguments);
      try{
        if(ret && typeof ret.then==="function"){
          return ret.then(function(x){
            filterCurrentList();
            return x;
          });
        }
      }catch(e){}
      setTimeout(filterCurrentList,300);
      return ret;
    };
    cloudLoadTaktik._tt181StrictFilterWrapped=true;
  }

  // Även efter render kan gammal kod ha behållit lista; säkerställ vid start.
  setTimeout(filterCurrentList,200);
  setTimeout(filterCurrentList,900);

  window.tt181StrictMineTaktik=strictMine;
  window.tt181TeamSharedTaktik=teamShared;
})();

/* === slut v181-strict-mine-owner-name === */


/* === v186-saves-scroll-keep-pitch ===
   Bas: 181.
   185 gav fungerande scroll men dolde planen. Det vill vi inte i Utgångsläge.
   Fix:
   - Scroll endast på #saves-list.
   - Planen/pitch-wrapper döljs aldrig.
   - Ingen bred DOM-sökning.
   - Rör inte Taktik, Formation eller Lag.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt186SavesScrollKeepPitch)return;
  window.__tt186SavesScrollKeepPitch=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function injectCss(){
    if(document.getElementById("tt186-saves-scroll-keep-pitch-css"))return;

    var style=document.createElement("style");
    style.id="tt186-saves-scroll-keep-pitch-css";
    style.textContent=[
      "/* v186: scroll i Utgångsläge men behåll planen */",

      "body.tt186-saves-open #pitch-wrapper {",
      "  display:block !important;",
      "}",

      "body.tt186-saves-open #panel-saves.on {",
      "  min-height:0 !important;",
      "  overflow:hidden !important;",
      "}",

      "body.tt186-saves-open #panel-saves.on > div {",
      "  min-height:0 !important;",
      "  overflow:hidden !important;",
      "}",

      "body.tt186-saves-open #saves-list {",
      "  display:block !important;",
      "  overflow-y:auto !important;",
      "  overflow-x:hidden !important;",
      "  -webkit-overflow-scrolling:touch !important;",
      "  overscroll-behavior:contain !important;",
      "  touch-action:pan-y !important;",
      "  min-height:120px !important;",
      "  padding-bottom:80px !important;",
      "}",

      "@media (max-width:720px){",
      "  body.tt186-saves-open #saves-list {",
      "    min-height:140px !important;",
      "    padding-bottom:105px !important;",
      "  }",
      "}"
    ].join("\n");

    document.head.appendChild(style);
  }

  function savesPanelOpen(){
    var p=document.getElementById("panel-saves");
    return !!(p && p.classList.contains("on"));
  }

  function calcAndApplyListHeight(){
    var list=document.getElementById("saves-list");
    var panel=document.getElementById("panel-saves");
    if(!list || !panel)return;

    if(!savesPanelOpen()){
      document.body.classList.remove("tt186-saves-open");
      list.style.maxHeight="";
      list.style.overflowY="";
      return;
    }

    document.body.classList.add("tt186-saves-open");

    // Viktigt: behåll planen synlig. Vi räknar bara hur mycket plats listan faktiskt
    // har från sin överkant till skärmens nederkant.
    var top=0;
    try{top=list.getBoundingClientRect().top;}catch(e){}
    var vh=window.innerHeight || document.documentElement.clientHeight || 700;

    // Lite marginal för nederkant/menyrad. Mer på mobil.
    var isMobile=window.matchMedia && window.matchMedia("(max-width:720px)").matches;
    var bottomGap=isMobile ? 110 : 82;

    var h=Math.floor(vh - top - bottomGap);

    // Om panelen ligger lågt får listan ändå en rimlig scrollhöjd.
    h=Math.max(isMobile ? 150 : 135, h);

    list.style.maxHeight=h+"px";
    list.style.overflowY="auto";
    list.style.overflowX="hidden";
    list.style.webkitOverflowScrolling="touch";
    list.style.touchAction="pan-y";

    try{
      panel.style.overflow="hidden";
      if(panel.firstElementChild){
        panel.firstElementChild.style.overflow="hidden";
        panel.firstElementChild.style.minHeight="0";
      }
    }catch(e){}
  }

  function apply(){
    setVersion();
    injectCss();

    if(savesPanelOpen()){
      calcAndApplyListHeight();
    }else{
      document.body.classList.remove("tt186-saves-open");
    }
  }

  if(typeof renderSavesList==="function" && !renderSavesList._tt186Wrapped){
    var oldRenderSavesList=renderSavesList;
    renderSavesList=function(){
      var r=oldRenderSavesList.apply(this,arguments);
      setTimeout(apply,0);
      setTimeout(apply,120);
      setTimeout(apply,350);
      return r;
    };
    renderSavesList._tt186Wrapped=true;
  }

  document.addEventListener("click",function(e){
    try{
      var tab=e.target.closest && e.target.closest(".tab");
      if(tab){
        setTimeout(apply,80);
        setTimeout(apply,300);
      }

      var inSaves=e.target.closest && e.target.closest("#panel-saves");
      if(inSaves){
        setTimeout(apply,120);
      }
    }catch(err){}
  },true);

  window.addEventListener("resize",function(){
    setTimeout(apply,80);
  });

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",function(){
      setTimeout(apply,0);
      setTimeout(apply,350);
      setTimeout(apply,1000);
    });
  }else{
    setTimeout(apply,0);
    setTimeout(apply,350);
    setTimeout(apply,1000);
  }

  window.tt186ApplySavesScroll=apply;
})();

/* === slut v186-saves-scroll-keep-pitch === */


