/* === v188-ios-saves-list-scroll ===
   Bas: 187.
   Fel: Utgångsläge-scroll fungerar på dator men inte på iPhone/iPad.
   Fix:
   - ge #saves-list tydlig pixelhöjd på iOS/mobil
   - lås touch-scroll till #saves-list
   - stoppa inte planen/andra paneler
   - rör endast Utgångsläge-listan
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt188IosSavesListScroll)return;
  window.__tt188IosSavesListScroll=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function isIosLike(){
    try{
      return /iPad|iPhone|iPod/.test(navigator.userAgent) ||
        (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
    }catch(e){
      return false;
    }
  }

  function savesPanelOpen(){
    var p=document.getElementById("panel-saves");
    return !!(p && p.classList.contains("on"));
  }

  function injectCss(){
    if(document.getElementById("tt188-ios-saves-list-scroll-css"))return;

    var style=document.createElement("style");
    style.id="tt188-ios-saves-list-scroll-css";
    style.textContent=[
      "/* v188: iOS-scroll endast i Utgångslägets fillista */",

      "body.tt188-saves-ios-open #panel-saves.on {",
      "  min-height:0 !important;",
      "  overflow:visible !important;",
      "}",

      "body.tt188-saves-ios-open #panel-saves.on > div {",
      "  min-height:0 !important;",
      "  overflow:visible !important;",
      "}",

      "body.tt188-saves-ios-open #saves-list {",
      "  display:block !important;",
      "  overflow-y:scroll !important;",
      "  overflow-x:hidden !important;",
      "  -webkit-overflow-scrolling:touch !important;",
      "  overscroll-behavior:contain !important;",
      "  touch-action:pan-y !important;",
      "  position:relative !important;",
      "  z-index:5 !important;",
      "  padding-bottom:120px !important;",
      "}",

      "body.tt188-saves-ios-open #pitch-wrapper {",
      "  display:flex !important;",
      "  justify-content:center !important;",
      "  align-items:center !important;",
      "  width:100% !important;",
      "  margin-left:auto !important;",
      "  margin-right:auto !important;",
      "}",

      "@supports (-webkit-touch-callout:none){",
      "  body.tt188-saves-ios-open #saves-list {",
      "    overflow-y:scroll !important;",
      "    -webkit-overflow-scrolling:touch !important;",
      "  }",
      "}"
    ].join("\n");

    document.head.appendChild(style);
  }

  function apply(){
    setVersion();
    injectCss();

    var list=document.getElementById("saves-list");
    var panel=document.getElementById("panel-saves");

    if(!list || !panel || !savesPanelOpen()){
      document.body.classList.remove("tt188-saves-ios-open");
      return;
    }

    document.body.classList.add("tt188-saves-ios-open");

    // iPhone/iPad behöver pixelhöjd, inte bara calc/max-height.
    var rect=list.getBoundingClientRect();
    var top=rect && rect.top ? rect.top : 0;

    var vh=window.innerHeight || document.documentElement.clientHeight || 700;

    // På iOS ligger browserns adressfält ofta och påverkar höjden.
    // Använd lite större marginal på touch-enheter.
    var touch=("ontouchstart" in window) || (navigator.maxTouchPoints||0)>0;
    var gap=touch ? 118 : 82;

    var h=Math.floor(vh - top - gap);

    // På iPhone kan listan annars bli för låg och då börjar sidan i stället scrolla.
    h=Math.max(touch ? 190 : 140, h);

    list.style.height=h+"px";
    list.style.maxHeight=h+"px";
    list.style.overflowY="scroll";
    list.style.overflowX="hidden";
    list.style.webkitOverflowScrolling="touch";
    list.style.touchAction="pan-y";
    list.style.position="relative";

    // Se till att föräldrar inte klipper bort scrollområdet på iOS.
    try{
      panel.style.overflow="visible";
      if(panel.firstElementChild){
        panel.firstElementChild.style.overflow="visible";
        panel.firstElementChild.style.minHeight="0";
      }
    }catch(e){}

    // Behåll planens centrering från 187.
    try{
      var pw=document.getElementById("pitch-wrapper");
      if(pw){
        pw.style.display="flex";
        pw.style.justifyContent="center";
        pw.style.alignItems="center";
        pw.style.width="100%";
        pw.style.marginLeft="auto";
        pw.style.marginRight="auto";
      }
    }catch(e){}
  }

  // Hjälp iOS att låta själva listan ta scrollen.
  document.addEventListener("touchmove",function(e){
    try{
      if(!savesPanelOpen())return;
      var list=document.getElementById("saves-list");
      if(!list)return;
      if(e.target && e.target.closest && e.target.closest("#saves-list")){
        // Rör inte eventet; listan ska få native-scroll.
        return;
      }
    }catch(err){}
  },{passive:true,capture:true});

  document.addEventListener("click",function(){
    setTimeout(apply,80);
    setTimeout(apply,300);
    setTimeout(apply,900);
  },true);

  window.addEventListener("resize",function(){
    setTimeout(apply,80);
    setTimeout(apply,350);
  });

  window.addEventListener("orientationchange",function(){
    setTimeout(apply,250);
    setTimeout(apply,900);
  });

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",function(){
      setTimeout(apply,0);
      setTimeout(apply,300);
      setTimeout(apply,1000);
    });
  }else{
    setTimeout(apply,0);
    setTimeout(apply,300);
    setTimeout(apply,1000);
  }

  window.tt188ApplyIosSavesScroll=apply;
})();

/* === slut v188-ios-saves-list-scroll === */


/* === v191-test-blockers-scroll-loop-crossdevice ===
   Bas: 190.
   Fixar bara tre saker för fortsatt funktionstest:
   1) Listor ska gå att nå längst ner utan gummibands-problem.
   2) Loop-knapparna i taktikfilm döljs visuellt.
   3) Samma användare på annan enhet kan se sina taktikfilmer i Mina via ownerName + team.
   Rör inte ritlogik, steglogik, save/load i övrigt eller Utgångsläge-namnbyte.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt191TestBlockers)return;
  window.__tt191TestBlockers=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function norm(v){
    return String(v||"").trim().toLowerCase();
  }

  function teamNorm(v){
    return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");
  }

  function profile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      if(raw)return JSON.parse(raw);
    }catch(e){}
    return null;
  }

  function isTaktik(obj){
    return !!(obj && Array.isArray(obj.steps));
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function sameName(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && norm(p.ownerName) && norm(m.ownerName) && norm(p.ownerName)===norm(m.ownerName));
  }

  function sameOwnerId(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && p.ownerId && m.ownerId && String(p.ownerId)===String(m.ownerId));
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function mineCrossDevice(tk){
    if(!isTaktik(tk))return false;

    var saved=!!idOf(tk);
    var m=meta(tk);

    // Lokalt nytt utkast innan första save.
    if(!saved && !(m && (m.ownerId || m.ownerName)))return true;

    // Samma enhet/profil: ownerId + namn om möjligt.
    if(m && m.ownerId && sameOwnerId(tk) && sameName(tk))return true;

    // Flera enheter: ownerId kan vara olika eftersom vi saknar riktig inloggning.
    // Då är namn + lag den praktiska identiteten tills vi bygger riktig fleranvändarlogin.
    if(sameName(tk) && sameTeam(tk))return true;

    return false;
  }

  function teamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function readOnlyTaktik(tk){
    try{
      if(typeof taktikScope!=="undefined" && taktikScope==="team" && teamShared(tk))return true;
    }catch(e){}
    return !mineCrossDevice(tk);
  }

  // Uppdatera bara taktikfilmsbehörighet. Utgångsläge lämnas till befintlig logik.
  var prevIsMine = (typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return mineCrossDevice(obj);
    return prevIsMine ? prevIsMine(obj) : true;
  };

  var prevTeamShared = (typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return teamShared(obj);
    return prevTeamShared ? prevTeamShared(obj) : false;
  };

  var prevVisible = (typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return scope==="team" ? teamShared(obj) : mineCrossDevice(obj);
    return prevVisible ? prevVisible(obj,scope) : true;
  };

  var prevReadOnly = (typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj))return readOnlyTaktik(obj);
    return prevReadOnly ? prevReadOnly(obj) : false;
  };

  try{
    if(window.tt176TaktikFs){
      window.tt176TaktikFs.isMine=mineCrossDevice;
      window.tt176TaktikFs.sharedToMyTeam=teamShared;
      window.tt176TaktikFs.visible=function(tk,scope){return scope==="team" ? teamShared(tk) : mineCrossDevice(tk);};
      window.tt176TaktikFs.readOnly=readOnlyTaktik;
    }
  }catch(e){}

  function injectCss(){
    if(document.getElementById("tt191-css"))return;

    var style=document.createElement("style");
    style.id="tt191-css";
    style.textContent=[
      "/* v191: mer bottenmarginal så sista raden går att använda */",
      "#saves-list, #taktik-list {",
      "  scroll-padding-bottom:180px !important;",
      "}",
      "#saves-list .tt191-list-bottom-spacer,",
      "#taktik-list .tt191-list-bottom-spacer {",
      "  display:block !important;",
      "  height:170px !important;",
      "  min-height:170px !important;",
      "  flex:0 0 170px !important;",
      "  pointer-events:none !important;",
      "}",
      "@media (max-width:720px){",
      "  #saves-list, #taktik-list {",
      "    scroll-padding-bottom:230px !important;",
      "  }",
      "  #saves-list .tt191-list-bottom-spacer,",
      "  #taktik-list .tt191-list-bottom-spacer {",
      "    height:230px !important;",
      "    min-height:230px !important;",
      "    flex-basis:230px !important;",
      "  }",
      "}",
      "/* v191: dölj Loop-kontroller utan att ändra animationens övriga logik */",
      "#play-loop, #ls-loop {",
      "  display:none !important;",
      "}"
    ].join("\n");

    document.head.appendChild(style);
  }

  function addBottomSpacer(listId){
    var list=document.getElementById(listId);
    if(!list)return;
    var old=list.querySelector(".tt191-list-bottom-spacer");
    if(old && old.parentNode===list){
      list.appendChild(old);
      return;
    }
    var spacer=document.createElement("div");
    spacer.className="tt191-list-bottom-spacer";
    spacer.setAttribute("aria-hidden","true");
    list.appendChild(spacer);
  }

  function hideLoopControls(){
    ["play-loop","ls-loop"].forEach(function(id){
      var input=document.getElementById(id);
      if(!input)return;

      try{input.checked=false;}catch(e){}
      try{input.style.display="none";}catch(e){}

      var p=input.parentElement;
      if(p && p.tagName && p.tagName.toLowerCase()==="label"){
        p.style.display="none";
      }
    });

    // Fallback: om texten Loop ligger i annan wrapper.
    try{
      document.querySelectorAll("label").forEach(function(lbl){
        var txt=(lbl.textContent||"").trim().toLowerCase();
        if(txt==="loop" || txt.endsWith(" loop")){
          if(lbl.querySelector("#play-loop,#ls-loop"))lbl.style.display="none";
        }
      });
    }catch(e){}
  }

  function applyListFixes(){
    setVersion();
    injectCss();
    hideLoopControls();
    addBottomSpacer("saves-list");
    addBottomSpacer("taktik-list");
  }

  function wrap(fnName){
    try{
      var fn=window[fnName];
      if(typeof fn!=="function" || fn._tt191Wrapped)return;
      var old=fn;
      window[fnName]=function(){
        var r=old.apply(this,arguments);
        setTimeout(applyListFixes,0);
        setTimeout(applyListFixes,150);
        return r;
      };
      window[fnName]._tt191Wrapped=true;
    }catch(e){}
  }

  wrap("renderSavesList");
  wrap("renderTaktikList");
  wrap("cloudLoadTaktik");
  wrap("cloudLoadSaves");

  document.addEventListener("click",function(){
    setTimeout(applyListFixes,80);
    setTimeout(applyListFixes,350);
  },true);

  window.addEventListener("resize",function(){
    setTimeout(applyListFixes,120);
  });

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",function(){
      setTimeout(applyListFixes,0);
      setTimeout(applyListFixes,300);
      setTimeout(applyListFixes,1000);
    });
  }else{
    setTimeout(applyListFixes,0);
    setTimeout(applyListFixes,300);
    setTimeout(applyListFixes,1000);
  }

  window.tt191ApplyListFixes=applyListFixes;
  window.tt191MineCrossDeviceTaktik=mineCrossDevice;
})();

/* === slut v191-test-blockers-scroll-loop-crossdevice === */


/* === v192-taktik-cross-device-load ===
   Bas: 191.
   Fel: samma användare på olika enheter ser Utgångsläge men inte egna Taktikfilmer.
   Orsak: gamla cloudLoadTaktik filtrerar sannolikt bort taktikfilmer innan de nya Mina-reglerna används.
   Fix:
   - Override endast cloudLoadTaktik.
   - Hämta alla taktikfilmer från molnet.
   - Mina = ownerName + team matchar aktuell profil, även om ownerId skiljer mellan enheter.
   - Lagets = sharedWithTeam=true + team matchar.
   Rör inte save, editorn, steg, ritningar, animation eller Utgångsläge.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt192TaktikCrossDeviceLoad)return;
  window.__tt192TaktikCrossDeviceLoad=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function clone(o){
    try{return JSON.parse(JSON.stringify(o));}catch(e){return o;}
  }

  function norm(v){
    return String(v||"").trim().toLowerCase();
  }

  function teamNorm(v){
    return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");
  }

  function profile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      if(raw)return JSON.parse(raw);
    }catch(e){}
    return null;
  }

  function isTaktik(obj){
    return !!(obj && Array.isArray(obj.steps));
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function sameName(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && norm(p.ownerName) && norm(m.ownerName) && norm(p.ownerName)===norm(m.ownerName));
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function sameOwnerId(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && p.ownerId && m.ownerId && String(p.ownerId)===String(m.ownerId));
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function isMineCrossDevice(tk){
    if(!isTaktik(tk))return false;

    var m=meta(tk);

    // Ny lokal osparad film
    if(!idOf(tk) && !(m && (m.ownerName || m.ownerId)))return true;

    // Samma enhet/profil
    if(m && m.ownerId && sameOwnerId(tk) && sameName(tk))return true;

    // Samma användare på annan enhet: namn + lag.
    if(sameName(tk) && sameTeam(tk))return true;

    return false;
  }

  function isTeamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function normalizeRow(row){
    var tk=clone((row && row.data) || {});
    if(!tk || typeof tk!=="object")tk={};
    if(!Array.isArray(tk.steps))tk.steps=[];
    tk.dbId=row.id;
    tk.id=row.id;
    tk.name=tk.name || row.name || "Taktikfilm";
    tk.folder=tk.folder || row.folder || "Taktik";
    tk.type="taktikfilm";

    // Normalisera äldre metadataformer om möjligt.
    if(!tk._meta && tk.meta)tk._meta=tk.meta;
    if(!tk._meta)tk._meta={};
    tk._meta.kind=tk._meta.kind || "taktikfilm";

    if(isMineCrossDevice(tk)){
      delete tk._readOnly;
      delete tk._openedFromTeam;
      delete tk.readOnly;
      delete tk.readonly;
      delete tk._readonly;
    }

    return tk;
  }

  function dedupe(list){
    var seen={};
    var out=[];
    (list||[]).forEach(function(tk){
      if(!tk)return;
      var key=tk.dbId ? "id:"+tk.dbId : "name:"+norm(tk.name)+"|folder:"+norm(tk.folder);
      if(seen[key])return;
      seen[key]=true;
      out.push(tk);
    });
    return out;
  }

  function rebuildFoldersLocal(){
    try{
      var seen={"Taktik":true,"Träning":true};
      taktikFolders=["Taktik","Träning"];
      (taktikFilmer||[]).forEach(function(tk){
        var f=tk.folder || "Taktik";
        if(f && !seen[f]){
          seen[f]=true;
          taktikFolders.push(f);
        }
      });
    }catch(e){}
  }

  // Uppdatera helpers också så listan och editorn använder samma regel.
  var prevIsMine=(typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return isMineCrossDevice(obj);
    return prevIsMine ? prevIsMine(obj) : true;
  };

  var prevTeam=(typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return isTeamShared(obj);
    return prevTeam ? prevTeam(obj) : false;
  };

  var prevVisible=(typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return scope==="team" ? isTeamShared(obj) : isMineCrossDevice(obj);
    return prevVisible ? prevVisible(obj,scope) : true;
  };

  var prevReadOnly=(typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj)){
      try{
        if(typeof taktikScope!=="undefined" && taktikScope==="team" && isTeamShared(obj))return true;
      }catch(e){}
      return !isMineCrossDevice(obj);
    }
    return prevReadOnly ? prevReadOnly(obj) : false;
  };

  try{
    if(window.tt176TaktikFs){
      window.tt176TaktikFs.isMine=isMineCrossDevice;
      window.tt176TaktikFs.sharedToMyTeam=isTeamShared;
      window.tt176TaktikFs.visible=function(tk,scope){return scope==="team" ? isTeamShared(tk) : isMineCrossDevice(tk);};
      window.tt176TaktikFs.readOnly=function(tk){
        try{
          if(typeof taktikScope!=="undefined" && taktikScope==="team" && isTeamShared(tk))return true;
        }catch(e){}
        return !isMineCrossDevice(tk);
      };
    }
  }catch(e){}

  cloudLoadTaktik=function(){
    setVersion();
    try{cloudStatus("Laddar taktik...","#7aaa88");}catch(e){}

    return fetch(SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?order=id.desc",{headers:supaHeaders()})
      .then(function(r){
        if(!r.ok)throw new Error("HTTP "+r.status);
        return r.json();
      })
      .then(function(rows){
        if(!Array.isArray(rows))rows=[];

        var loaded=[];
        rows.forEach(function(row){
          var data=row && row.data;
          var rowIsTaktik=(row && row.type==="taktikfilm") || (data && Array.isArray(data.steps));
          if(!rowIsTaktik)return;

          var tk=normalizeRow(row);

          // Taktikfilm måste ha minst startläge + ett steg.
          // Bevara samma krav som tidigare fungerande sparning.
          if(!tk.steps || tk.steps.length<2)return;

          if(isMineCrossDevice(tk) || isTeamShared(tk)){
            loaded.push(tk);
          }
        });

        taktikFilmer=dedupe(loaded);
        rebuildFoldersLocal();

        try{
          if(typeof taktikScope==="undefined" || !taktikScope)taktikScope="mine";
          if(typeof currentTaktikFolder==="undefined" || !currentTaktikFolder)currentTaktikFolder="Alla";
        }catch(e){}

        try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}
        try{if(typeof tt191ApplyListFixes==="function")tt191ApplyListFixes();}catch(e){}

        try{
          var mineCount=taktikFilmer.filter(isMineCrossDevice).length;
          var teamCount=taktikFilmer.filter(isTeamShared).length;
          cloudStatus("✅ Taktik laddad: Mina "+mineCount+" · Lagets "+teamCount,"#4ae87a");
        }catch(e){
          try{cloudStatus("✅ Taktik laddad","#4ae87a");}catch(e2){}
        }

        return taktikFilmer;
      })
      .catch(function(err){
        try{cloudStatus("❌ Kunde inte ladda taktik: "+err.message,"#e84a4a");}catch(e){}
        throw err;
      });
  };

  // Ladda om taktik efter att den nya load-funktionen finns på plats.
  setTimeout(function(){
    try{cloudLoadTaktik();}catch(e){}
  },250);

  window.tt192TaktikIsMine=isMineCrossDevice;
  window.tt192TaktikIsTeamShared=isTeamShared;
})();

/* === slut v192-taktik-cross-device-load === */


/* === v200-taktik-load-no-step-filter ===
   Bas: v192.
   Problem: Taktikfilm har korrekt _meta men syns inte i Mina på annan enhet.
   Trolig orsak: cloudLoadTaktik filtrerar bort filmer som inte har minst 2 steg.
   Fix:
   - Override endast cloudLoadTaktik.
   - Egna taktikfilmer visas om ownerName + team matchar, även om steps bara har 0/1 steg.
   - Delade taktikfilmer visas i Lagets om sharedWithTeam + team matchar.
   - Rör inte save, editorn, steglogik, animation eller Utgångsläge.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt200TaktikLoadNoStepFilter)return;
  window.__tt200TaktikLoadNoStepFilter=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function clone(o){
    try{return JSON.parse(JSON.stringify(o));}catch(e){return o;}
  }

  function norm(v){
    return String(v||"").trim().toLowerCase();
  }

  function teamNorm(v){
    return String(v||"").trim().toUpperCase().replace(/\s+/g,"-");
  }

  function profile(){
    try{
      if(typeof getUserProfile==="function"){
        var p=getUserProfile();
        if(p)return p;
      }
    }catch(e){}
    try{
      var raw=localStorage.getItem("tt_profile_v1");
      if(raw)return JSON.parse(raw);
    }catch(e){}
    return null;
  }

  function isTaktik(obj){
    return !!(obj && (Array.isArray(obj.steps) || obj.type==="taktikfilm"));
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function sameName(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && norm(p.ownerName) && norm(m.ownerName) && norm(p.ownerName)===norm(m.ownerName));
  }

  function sameTeam(tk){
    var p=profile(), m=meta(tk);
    if(!p || !m)return false;
    var pt=teamNorm(p.teamId || p.teamCode || p.teamName);
    var mt=teamNorm(m.teamId || m.teamCode || m.teamName);
    return !!(pt && mt && pt===mt);
  }

  function sameOwnerId(tk){
    var p=profile(), m=meta(tk);
    return !!(p && m && p.ownerId && m.ownerId && String(p.ownerId)===String(m.ownerId));
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function isMineCrossDevice(tk){
    if(!isTaktik(tk))return false;

    var m=meta(tk);

    if(!idOf(tk) && !(m && (m.ownerName || m.ownerId)))return true;

    if(m && m.ownerId && sameOwnerId(tk) && sameName(tk))return true;

    // Viktig regel för flera enheter utan riktig login.
    if(sameName(tk) && sameTeam(tk))return true;

    return false;
  }

  function isTeamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function normalizeRow(row){
    var tk=clone((row && row.data) || {});
    if(!tk || typeof tk!=="object")tk={};

    if(!Array.isArray(tk.steps))tk.steps=[];

    tk.dbId=row.id;
    tk.id=row.id;
    tk.name=tk.name || row.name || "Taktikfilm";
    tk.folder=tk.folder || row.folder || "Taktik";
    tk.type="taktikfilm";

    if(!tk._meta && tk.meta)tk._meta=tk.meta;
    if(!tk._meta)tk._meta={};
    tk._meta.kind=tk._meta.kind || "taktikfilm";

    if(isMineCrossDevice(tk)){
      delete tk._readOnly;
      delete tk._openedFromTeam;
      delete tk.readOnly;
      delete tk.readonly;
      delete tk._readonly;
    }

    return tk;
  }

  function dedupe(list){
    var seen={}, out=[];
    (list||[]).forEach(function(tk){
      if(!tk)return;
      var key=tk.dbId ? "id:"+tk.dbId : "name:"+norm(tk.name)+"|folder:"+norm(tk.folder);
      if(seen[key])return;
      seen[key]=true;
      out.push(tk);
    });
    return out;
  }

  function rebuildFoldersLocal(){
    try{
      var seen={"Taktik":true,"Träning":true};
      taktikFolders=["Taktik","Träning"];
      (taktikFilmer||[]).forEach(function(tk){
        var f=tk.folder || "Taktik";
        if(f && !seen[f]){
          seen[f]=true;
          taktikFolders.push(f);
        }
      });
    }catch(e){}
  }

  // Samma helpers som listan använder.
  var prevIsMine=(typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return isMineCrossDevice(obj);
    return prevIsMine ? prevIsMine(obj) : true;
  };

  var prevTeam=(typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return isTeamShared(obj);
    return prevTeam ? prevTeam(obj) : false;
  };

  var prevVisible=(typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return scope==="team" ? isTeamShared(obj) : isMineCrossDevice(obj);
    return prevVisible ? prevVisible(obj,scope) : true;
  };

  var prevReadOnly=(typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj)){
      try{
        if(typeof taktikScope!=="undefined" && taktikScope==="team" && isTeamShared(obj))return true;
      }catch(e){}
      return !isMineCrossDevice(obj);
    }
    return prevReadOnly ? prevReadOnly(obj) : false;
  };

  cloudLoadTaktik=function(){
    setVersion();
    try{cloudStatus("Laddar taktik...","#7aaa88");}catch(e){}

    return fetch(SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?order=id.desc",{headers:supaHeaders()})
      .then(function(r){
        if(!r.ok)throw new Error("HTTP "+r.status);
        return r.json();
      })
      .then(function(rows){
        if(!Array.isArray(rows))rows=[];

        var loaded=[];
        rows.forEach(function(row){
          var data=row && row.data;
          var rowIsTaktik=(row && row.type==="taktikfilm") || (data && (Array.isArray(data.steps) || data.type==="taktikfilm"));
          if(!rowIsTaktik)return;

          var tk=normalizeRow(row);

          // OBS v200: inget steps.length-filter här.
          // Egna molnfiler ska synas i Mina även om de bara har startläge/ett steg.
          if(isMineCrossDevice(tk) || isTeamShared(tk)){
            loaded.push(tk);
          }
        });

        taktikFilmer=dedupe(loaded);
        rebuildFoldersLocal();

        try{
          if(typeof taktikScope==="undefined" || !taktikScope)taktikScope="mine";
          if(typeof currentTaktikFolder==="undefined" || !currentTaktikFolder)currentTaktikFolder="Alla";
        }catch(e){}

        try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}
        try{if(typeof tt191ApplyListFixes==="function")tt191ApplyListFixes();}catch(e){}

        try{
          var mineCount=taktikFilmer.filter(isMineCrossDevice).length;
          var teamCount=taktikFilmer.filter(isTeamShared).length;
          cloudStatus("✅ Taktik laddad: Mina "+mineCount+" · Lagets "+teamCount,"#4ae87a");
        }catch(e){
          try{cloudStatus("✅ Taktik laddad","#4ae87a");}catch(e2){}
        }

        return taktikFilmer;
      })
      .catch(function(err){
        try{cloudStatus("❌ Kunde inte ladda taktik: "+err.message,"#e84a4a");}catch(e){}
        throw err;
      });
  };

  setTimeout(function(){
    try{cloudLoadTaktik();}catch(e){}
  },250);

  window.tt200TaktikIsMine=isMineCrossDevice;
  window.tt200TaktikIsTeamShared=isTeamShared;
})();

/* === slut v200-taktik-load-no-step-filter === */


/* === v201-taktik-profile-name-fallback ===
   Bas: v200.
   Problem: odelade taktikfilmer syns inte i Mina på annan enhet,
   men de syns om filen är delad. Det betyder att team-match fungerar,
   men person/namn-match faller bort.
   Fix:
   - Taktikfilmens "Mina"-matchning läser användarnamn från fler möjliga profilfält.
   - Fallback: läs profilknappens text, t.ex. "Mattias · MUNKA-IF-P2013".
   - Mina = ownerName + team matchar.
   - Lagets = sharedWithTeam + team matchar.
   Rör inte Utgångsläge, save, redigering, steg eller animation.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt201TaktikProfileNameFallback)return;
  window.__tt201TaktikProfileNameFallback=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function clone(o){try{return JSON.parse(JSON.stringify(o));}catch(e){return o;}}
  function clean(v){return String(v||"").trim();}
  function norm(v){return clean(v).toLowerCase();}
  function teamNorm(v){return clean(v).toUpperCase().replace(/\s+/g,"-");}

  function rawProfile(){
    try{if(typeof getUserProfile==="function"){var p=getUserProfile(); if(p)return p;}}catch(e){}
    try{if(typeof getProfileSafeV10==="function"){var p2=getProfileSafeV10(); if(p2)return p2;}}catch(e){}
    try{var raw=localStorage.getItem("tt_profile_v1"); if(raw)return JSON.parse(raw);}catch(e){}
    return {};
  }

  function profileButtonText(){
    try{
      var btn=document.getElementById("btn-profile-team") ||
              document.getElementById("btn-profile-v59") ||
              document.getElementById("btn-profile-v102") ||
              document.querySelector("button[id*='profile'],button[title*='Profil'],button[title*='profil']");
      return btn ? clean(btn.textContent||"") : "";
    }catch(e){
      return "";
    }
  }

  function profileNames(){
    var p=rawProfile();
    var out=[];
    ["ownerName","name","userName","username","coachName","trainerName","displayName","createdBy"].forEach(function(k){
      if(p && p[k])out.push(p[k]);
    });

    var txt=profileButtonText();
    if(txt){
      txt=txt.replace(/^👤\s*/,"").trim();
      var first=txt.split("·")[0].trim();
      if(first)out.push(first);
    }

    var seen={};
    return out.map(clean).filter(function(x){
      var k=norm(x);
      if(!k || seen[k])return false;
      seen[k]=true;
      return true;
    });
  }

  function profileTeams(){
    var p=rawProfile();
    var out=[];
    ["teamId","teamCode","teamName","team","club","clubName"].forEach(function(k){
      if(p && p[k])out.push(p[k]);
    });

    var txt=profileButtonText();
    if(txt && txt.indexOf("·")>=0){
      var team=txt.split("·").slice(1).join("·").trim();
      if(team)out.push(team);
    }

    var seen={};
    return out.map(teamNorm).filter(function(x){
      if(!x || seen[x])return false;
      seen[x]=true;
      return true;
    });
  }

  function isTaktik(obj){
    return !!(obj && (Array.isArray(obj.steps) || obj.type==="taktikfilm"));
  }

  function meta(tk){
    if(!tk)return {};
    if(tk._meta)return tk._meta;
    if(tk.meta)return tk.meta;
    if(tk.data && tk.data._meta)return tk.data._meta;
    return {};
  }

  function idOf(tk){
    return String((tk && (tk.dbId || tk.id)) || "").trim();
  }

  function sameName(tk){
    var m=meta(tk);
    var owner=norm(m.ownerName || m.createdBy || "");
    if(!owner)return false;
    return profileNames().some(function(n){return norm(n)===owner;});
  }

  function sameOwnerId(tk){
    var p=rawProfile(), m=meta(tk);
    return !!(p && m && p.ownerId && m.ownerId && String(p.ownerId)===String(m.ownerId));
  }

  function sameTeam(tk){
    var m=meta(tk);
    var mt=[m.teamId,m.teamCode,m.teamName,m.team].map(teamNorm).filter(Boolean);
    var pt=profileTeams();
    if(!mt.length || !pt.length)return false;
    return mt.some(function(a){return pt.indexOf(a)>=0;});
  }

  function isMineCrossDevice(tk){
    if(!isTaktik(tk))return false;

    var m=meta(tk);

    if(!idOf(tk) && !(m && (m.ownerName || m.ownerId)))return true;

    if(m && m.ownerId && sameOwnerId(tk) && sameName(tk))return true;

    // Viktigt: samma användare på annan enhet.
    if(sameName(tk) && sameTeam(tk))return true;

    return false;
  }

  function isTeamShared(tk){
    var m=meta(tk);
    return !!(isTaktik(tk) && m && m.sharedWithTeam && sameTeam(tk));
  }

  function normalizeRow(row){
    var tk=clone((row && row.data) || {});
    if(!tk || typeof tk!=="object")tk={};
    if(!Array.isArray(tk.steps))tk.steps=[];
    tk.dbId=row.id;
    tk.id=row.id;
    tk.name=tk.name || row.name || "Taktikfilm";
    tk.folder=tk.folder || row.folder || "Taktik";
    tk.type="taktikfilm";
    if(!tk._meta && tk.meta)tk._meta=tk.meta;
    if(!tk._meta)tk._meta={};
    tk._meta.kind=tk._meta.kind || "taktikfilm";

    if(isMineCrossDevice(tk)){
      delete tk._readOnly;
      delete tk._openedFromTeam;
      delete tk.readOnly;
      delete tk.readonly;
      delete tk._readonly;
    }

    return tk;
  }

  function dedupe(list){
    var seen={}, out=[];
    (list||[]).forEach(function(tk){
      if(!tk)return;
      var key=tk.dbId ? "id:"+tk.dbId : "name:"+norm(tk.name)+"|folder:"+norm(tk.folder);
      if(seen[key])return;
      seen[key]=true;
      out.push(tk);
    });
    return out;
  }

  function rebuildFoldersLocal(){
    try{
      var seen={"Taktik":true,"Träning":true};
      taktikFolders=["Taktik","Träning"];
      (taktikFilmer||[]).forEach(function(tk){
        var f=tk.folder || "Taktik";
        if(f && !seen[f]){
          seen[f]=true;
          taktikFolders.push(f);
        }
      });
    }catch(e){}
  }

  // Skriv över bara taktikfilmshjälpare.
  var prevIsMine=(typeof isMineV10==="function") ? isMineV10 : null;
  isMineV10=function(obj){
    if(isTaktik(obj))return isMineCrossDevice(obj);
    return prevIsMine ? prevIsMine(obj) : true;
  };

  var prevTeam=(typeof isSameTeamSharedV10==="function") ? isSameTeamSharedV10 : null;
  isSameTeamSharedV10=function(obj){
    if(isTaktik(obj))return isTeamShared(obj);
    return prevTeam ? prevTeam(obj) : false;
  };

  var prevVisible=(typeof isFileVisibleInScopeV10==="function") ? isFileVisibleInScopeV10 : null;
  isFileVisibleInScopeV10=function(obj,scope){
    if(isTaktik(obj))return scope==="team" ? isTeamShared(obj) : isMineCrossDevice(obj);
    return prevVisible ? prevVisible(obj,scope) : true;
  };

  var prevReadOnly=(typeof isReadOnlyFileV10==="function") ? isReadOnlyFileV10 : null;
  isReadOnlyFileV10=function(obj){
    if(isTaktik(obj)){
      try{
        if(typeof taktikScope!=="undefined" && taktikScope==="team" && isTeamShared(obj))return true;
      }catch(e){}
      return !isMineCrossDevice(obj);
    }
    return prevReadOnly ? prevReadOnly(obj) : false;
  };

  cloudLoadTaktik=function(){
    setVersion();
    try{cloudStatus("Laddar taktik...","#7aaa88");}catch(e){}

    return fetch(SUPA_URL+"/rest/v1/"+SUPA_TABLE+"?order=id.desc",{headers:supaHeaders()})
      .then(function(r){
        if(!r.ok)throw new Error("HTTP "+r.status);
        return r.json();
      })
      .then(function(rows){
        if(!Array.isArray(rows))rows=[];

        var loaded=[];
        rows.forEach(function(row){
          var data=row && row.data;
          var rowIsTaktik=(row && row.type==="taktikfilm") ||
            (data && (Array.isArray(data.steps) || data.type==="taktikfilm" || (data._meta && data._meta.kind==="taktikfilm")));
          if(!rowIsTaktik)return;

          var tk=normalizeRow(row);

          // Inget stegfilter: egna filer ska synas även om de har få steg.
          if(isMineCrossDevice(tk) || isTeamShared(tk)){
            loaded.push(tk);
          }
        });

        taktikFilmer=dedupe(loaded);
        rebuildFoldersLocal();

        try{
          if(typeof taktikScope==="undefined" || !taktikScope)taktikScope="mine";
          if(typeof currentTaktikFolder==="undefined" || !currentTaktikFolder)currentTaktikFolder="Alla";
        }catch(e){}

        try{if(typeof renderTaktikList==="function")renderTaktikList();}catch(e){}
        try{if(typeof tt191ApplyListFixes==="function")tt191ApplyListFixes();}catch(e){}

        try{
          var mineCount=taktikFilmer.filter(isMineCrossDevice).length;
          var teamCount=taktikFilmer.filter(isTeamShared).length;
          cloudStatus("✅ Taktik laddad: Mina "+mineCount+" · Lagets "+teamCount,"#4ae87a");
        }catch(e){
          try{cloudStatus("✅ Taktik laddad","#4ae87a");}catch(e2){}
        }

        return taktikFilmer;
      })
      .catch(function(err){
        try{cloudStatus("❌ Kunde inte ladda taktik: "+err.message,"#e84a4a");}catch(e){}
        throw err;
      });
  };

  setTimeout(function(){try{cloudLoadTaktik();}catch(e){}},250);

  window.tt201TaktikIsMine=isMineCrossDevice;
  window.tt201TaktikIsTeamShared=isTeamShared;
  window.tt201ProfileNames=profileNames;
  window.tt201ProfileTeams=profileTeams;
})();

/* === slut v201-taktik-profile-name-fallback === */


/* === v204-new-step-target-only ===
   Bas: 201.
   Syfte:
   - När + Nytt steg används ska nya steget vara en ren slutbild.
   - Slutpositioner från rörelsepilar ska följa med.
   - Själva rörelsepilarna ska inte följa med.
   - Vanliga ritningar ska inte följa med.
   Viktigt:
   - Bygger på befintlig tt145-rörelsemotor om den finns.
   - Rör inte spara/ladda, Mina/Lagets, delning eller animation.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt204NewStepTargetOnly)return;
  window.__tt204NewStepTargetOnly=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function clone(o){
    try{return JSON.parse(JSON.stringify(o));}catch(e){return o;}
  }

  function currentTk(){
    try{
      if(typeof tt145CurrentTk==="function")return tt145CurrentTk();
    }catch(e){}
    try{
      if(typeof tt76Current==="function")return tt76Current();
    }catch(e){}
    try{
      if(typeof editingTaktikIdx!=="undefined" && editingTaktikIdx!==null){
        return taktikFilmer && taktikFilmer[editingTaktikIdx];
      }
    }catch(e){}
    return null;
  }

  function label(idx){
    try{
      if(typeof tt145Label==="function")return tt145Label(idx);
    }catch(e){}
    try{
      if(typeof tt76Label==="function")return tt76Label(idx);
    }catch(e){}
    return idx===0 ? "Startläge" : "Steg "+idx;
  }

  function safeStep(step,idx){
    try{
      if(typeof tt145SafeStep==="function")return tt145SafeStep(step,idx);
    }catch(e){}
    try{
      if(typeof tt76SafeStep==="function")return tt76SafeStep(step,idx);
    }catch(e){}
    step=step||{};
    if(!Array.isArray(step.players))step.players=[];
    if(!step.ball)step.ball={x:W/2,y:H/2};
    if(!step.label)step.label=label(idx||0);
    return step;
  }

  function normalizeFilm(tk){
    try{
      if(typeof tt145Normalize==="function")return tt145Normalize(tk);
    }catch(e){}
    try{
      if(typeof tt76NormalizeFilm==="function")return tt76NormalizeFilm(tk);
    }catch(e){}
    if(tk && !Array.isArray(tk.steps))tk.steps=[];
    return tk;
  }

  function isReadOnly(tk){
    try{
      if(typeof tt76IsReadOnly==="function")return !!tt76IsReadOnly(tk);
    }catch(e){}
    try{
      if(typeof isReadOnlyFileV10==="function")return !!isReadOnlyFileV10(tk);
    }catch(e){}
    return false;
  }

  function setPos(step,id,pos){
    if(!step||!pos)return;
    if(String(id)==="ball"){
      step.ball=step.ball||{x:pos.x,y:pos.y};
      step.ball.x=pos.x;
      step.ball.y=pos.y;
      return;
    }
    var p=(step.players||[]).find(function(x){return String(x.id)===String(id);});
    if(p){
      p.x=pos.x;
      p.y=pos.y;
    }
  }

  function movementEndpointMapFromStep(step){
    var out={};
    var list=(step && step.movementPaths) || [];
    if(!Array.isArray(list))return out;
    list.forEach(function(mp){
      if(!mp || !mp.playerId || !mp.pts || mp.pts.length<2)return;
      var ep=mp.pts[mp.pts.length-1];
      out[String(mp.playerId)]={x:ep.x,y:ep.y};
    });
    return out;
  }

  function cleanNewStep(step){
    if(!step || typeof step!=="object")return step;

    // Vanliga ritningar.
    step.arrows=[];
    step.labels=[];
    step.freehandPaths=[];
    step.zones=[];

    // Rörelsepil hör till föregående steg, inte nya slutbilden.
    step.movementPaths=[];

    return step;
  }

  function makeTargetOnlyStep(){
    var tk=normalizeFilm(currentTk());
    if(!tk || !Array.isArray(tk.steps))return false;
    if(isReadOnly(tk))return false;

    var oldIdx=(typeof editingStepIdx==="number") ? editingStepIdx : 0;

    // 1. Spara aktuellt steg med befintlig rörelsemotor.
    // tt145SaveCurrentStep gör det viktiga: rörelsepilens endpoint blir spelarens slutposition.
    try{
      if(typeof tt145SaveCurrentStep==="function"){
        tt145SaveCurrentStep({allowAutoCreate:false});
      }else if(typeof tt76SaveCurrentStep==="function"){
        tt76SaveCurrentStep({allowAutoCreate:false});
      }else if(typeof autoSaveCurrentStepLocalV16==="function"){
        autoSaveCurrentStepLocalV16();
      }
    }catch(e){}

    tk=normalizeFilm(currentTk());
    if(!tk || !Array.isArray(tk.steps) || !tk.steps[oldIdx])return false;

    var source=safeStep(tk.steps[oldIdx],oldIdx);

    // Extra säkerhet: om någon äldre motor inte redan skrev endpointen till positionen,
    // gör vi det direkt här innan nya steget skapas.
    var ends=movementEndpointMapFromStep(source);
    Object.keys(ends).forEach(function(id){
      setPos(source,id,ends[id]);
    });
    tk.steps[oldIdx]=source;

    // 2. Nya steget blir kopia av målbilden/slutbilden.
    var newStep=safeStep(clone(source),oldIdx+1);
    cleanNewStep(newStep);
    newStep.label=label(oldIdx+1);

    try{if(typeof saveTaktikUndo==="function")saveTaktikUndo();}catch(e){}

    tk.steps.splice(oldIdx+1,0,newStep);
    editingStepIdx=oldIdx+1;

    try{normalizeFilm(tk);}catch(e){}

    // 3. Öppna nya steget utan att autospara över det gamla.
    try{
      if(typeof tt145GoToStep==="function"){
        tt145GoToStep(editingStepIdx,false);
      }else if(typeof tt76LoadStep==="function"){
        tt76LoadStep(editingStepIdx,{animate:false,skipSave:true});
      }else if(typeof updateEditStepUI==="function"){
        updateEditStepUI();
      }
    }catch(e){
      try{restoreSnap(newStep);render();}catch(e2){}
    }

    try{if(typeof tt76MarkDirty==="function")tt76MarkDirty();else taktikDirtyV17=true;}catch(e){}
    try{showToast("Nytt steg skapat");}catch(e){}

    return true;
  }

  // Skriv över den namngivna funktionen så även senare rebindingar använder rätt logik.
  try{
    window.tt145AddStep=makeTargetOnlyStep;
    if(typeof tt145AddStep!=="undefined")tt145AddStep=makeTargetOnlyStep;
  }catch(e){}

  function captureClick(e){
    var btn=e.target && e.target.closest ? e.target.closest("#btn-edit-add-step") : null;
    if(!btn)return;
    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation)e.stopImmediatePropagation();
    makeTargetOnlyStep();
    return false;
  }

  // Capture på document gör att vi inte behöver röra renderlogiken eller klona om hela UI:t.
  document.addEventListener("click",captureClick,true);

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",setVersion);
  }else{
    setVersion();
  }
  setTimeout(setVersion,300);
  setTimeout(setVersion,1000);

  window.tt204MakeTargetOnlyStep=makeTargetOnlyStep;
  window.tt204CleanNewStep=cleanNewStep;
})();

/* === slut v204-new-step-target-only === */


/* === v205-quick-formation-in-saves ===
   Bas: 204.
   Syfte:
   - Göra formationsval åtkomligt även inne i Utgångsläge.
   - Inte flytta hela formationspanelen.
   - Lägga en kompakt, hopfälld väljare i panelen Utgångsläge.
   - När den öppnas visas format + formationer.
   - Använder samma FORMATIONS/initPlayers/buildFormationBtns som vanliga Formation-fliken.
   Rör inte Taktikfilm, spara/ladda, Mina/Lagets, steg eller animation.
   Endast app.js behöver bytas.
*/

(function(){
  if(window.__tt205QuickFormationInSaves)return;
  window.__tt205QuickFormationInSaves=true;

  function setVersion(){
    try{
      var spans=document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]');
      spans.forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function injectStyle(){
    if(document.getElementById("tt205-style"))return;
    var st=document.createElement("style");
    st.id="tt205-style";
    st.textContent=[
      "#tt205-quick-formation{margin:0 0 6px 0;border:1px solid #243b2a;border-radius:8px;background:rgba(17,26,20,.78);overflow:hidden}",
      "#tt205-qf-head{width:100%;display:flex;align-items:center;justify-content:space-between;gap:6px;background:transparent;border:0;color:#4ae87a;padding:5px 8px;font-size:.74rem;font-weight:800;font-family:Arial Narrow,Arial,sans-serif;text-transform:uppercase;letter-spacing:.3px;cursor:pointer}",
      "#tt205-qf-current{color:#e8c84a;font-weight:900;text-transform:none;letter-spacing:0;font-size:.78rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}",
      "#tt205-qf-body{display:none;padding:6px 7px 7px;border-top:1px solid #243b2a}",
      "#tt205-quick-formation.open #tt205-qf-body{display:block}",
      "#tt205-qf-row{display:flex;gap:5px;align-items:center;margin-bottom:6px}",
      "#tt205-qf-format{background:#111a14;color:#edf5ee;border:1px solid #2d4a35;border-radius:5px;padding:4px 7px;font-size:.72rem;font-family:Arial Narrow,Arial,sans-serif}",
      "#tt205-qf-buttons{display:flex;gap:4px;flex-wrap:wrap;max-height:88px;overflow:auto;-webkit-overflow-scrolling:touch}",
      "#tt205-qf-buttons .btn{padding:4px 7px;font-size:.7rem}",
      "#tt205-qf-buttons .btn.on{border-color:#4ae87a;color:#4ae87a;background:rgba(74,232,122,.08)}"
    ].join("\n");
    document.head.appendChild(st);
  }

  function currentFormationName(){
    try{
      var active=document.querySelector("#formation-btns .btn.on");
      if(active && active.textContent)return active.textContent.trim();
    }catch(e){}
    try{
      if(typeof _defaultFormation!=="undefined" && _defaultFormation)return _defaultFormation;
    }catch(e){}
    return "4-4-2";
  }

  function currentFormat(){
    try{
      if(typeof format!=="undefined" && format)return parseInt(format,10)||11;
    }catch(e){}
    try{
      var sel=document.getElementById("fmt-sel");
      if(sel)return parseInt(sel.value,10)||11;
    }catch(e){}
    return 11;
  }

  function formationsFor(fmt){
    try{
      return (FORMATIONS && FORMATIONS[fmt]) ? FORMATIONS[fmt] : (FORMATIONS && FORMATIONS[11]) || ["4-4-2"];
    }catch(e){
      return ["4-4-2"];
    }
  }

  function updateLabel(){
    try{
      var cur=document.getElementById("tt205-qf-current");
      if(cur)cur.textContent=currentFormat()+"v"+currentFormat()+" · "+currentFormationName();
    }catch(e){}
  }

  function renderButtons(){
    var box=document.getElementById("tt205-qf-buttons");
    if(!box)return;
    var fmt=currentFormat();
    var active=currentFormationName();
    box.innerHTML="";
    formationsFor(fmt).forEach(function(f){
      var b=document.createElement("button");
      b.className="btn"+(f===active?" on":"");
      b.type="button";
      b.textContent=f;
      b.addEventListener("click",function(){
        applyFormation(fmt,f);
      });
      box.appendChild(b);
    });
    updateLabel();
  }

  function syncOriginalFormationButtons(fmt,f){
    try{
      if(typeof buildFormationBtns==="function")buildFormationBtns();
      var btns=document.querySelectorAll("#formation-btns .btn");
      btns.forEach(function(b){
        if((b.textContent||"").trim()===f){
          b.classList.add("on");
        }else{
          b.classList.remove("on");
        }
      });
    }catch(e){}
  }

  function applyFormation(fmt,f){
    try{
      format=parseInt(fmt,10)||11;
    }catch(e){}

    try{
      var sel=document.getElementById("fmt-sel");
      if(sel)sel.value=String(format);
    }catch(e){}

    try{
      syncOriginalFormationButtons(format,f);
    }catch(e){}

    try{
      if(typeof initPlayers==="function")initPlayers(f);
    }catch(e){}

    try{
      if(typeof render==="function")render();
    }catch(e){}

    try{
      if(typeof showToast==="function")showToast("Formation: "+f);
    }catch(e){}

    renderButtons();
  }

  function buildUi(){
    injectStyle();

    var panel=document.getElementById("panel-saves");
    if(!panel)return;

    if(document.getElementById("tt205-quick-formation")){
      renderButtons();
      updateLabel();
      return;
    }

    var inner=panel.querySelector("div");
    if(!inner)return;

    var wrap=document.createElement("div");
    wrap.id="tt205-quick-formation";

    var head=document.createElement("button");
    head.id="tt205-qf-head";
    head.type="button";
    head.innerHTML='<span>Formation</span><span id="tt205-qf-current"></span><span id="tt205-qf-caret">▾</span>';
    head.addEventListener("click",function(){
      wrap.classList.toggle("open");
      var caret=document.getElementById("tt205-qf-caret");
      if(caret)caret.textContent=wrap.classList.contains("open")?"▴":"▾";
    });

    var body=document.createElement("div");
    body.id="tt205-qf-body";

    var row=document.createElement("div");
    row.id="tt205-qf-row";

    var sel=document.createElement("select");
    sel.id="tt205-qf-format";
    [11,9,7,5].forEach(function(n){
      var opt=document.createElement("option");
      opt.value=String(n);
      opt.textContent=n+"v"+n;
      sel.appendChild(opt);
    });
    sel.value=String(currentFormat());
    sel.addEventListener("change",function(){
      var fmt=parseInt(sel.value,10)||11;
      try{
        format=fmt;
        var top=document.getElementById("fmt-sel");
        if(top)top.value=String(fmt);
        if(typeof buildFormationBtns==="function")buildFormationBtns();
      }catch(e){}
      renderButtons();
    });

    var hint=document.createElement("span");
    hint.style.cssText="font-size:.66rem;color:#7aaa88;white-space:nowrap";
    hint.textContent="Välj uppställning";

    row.appendChild(sel);
    row.appendChild(hint);

    var buttons=document.createElement("div");
    buttons.id="tt205-qf-buttons";

    body.appendChild(row);
    body.appendChild(buttons);
    wrap.appendChild(head);
    wrap.appendChild(body);

    // Lägg överst i Utgångsläge-panelen, precis ovanför Spara/Spara som-raden.
    inner.insertBefore(wrap,inner.firstChild);

    renderButtons();
    updateLabel();
  }

  // Håll etiketten rimligt uppdaterad utan att röra befintlig renderlogik.
  var oldBuild=typeof buildFormationBtns==="function" ? buildFormationBtns : null;
  if(oldBuild && !oldBuild.__tt205Wrapped){
    var wrapped=function(){
      var res=oldBuild.apply(this,arguments);
      setTimeout(function(){try{renderButtons();updateLabel();}catch(e){}},0);
      return res;
    };
    wrapped.__tt205Wrapped=true;
    buildFormationBtns=wrapped;
  }

  if(document.readyState==="loading"){
    document.addEventListener("DOMContentLoaded",function(){
      setVersion();
      buildUi();
    });
  }else{
    setVersion();
    buildUi();
  }

  setTimeout(buildUi,300);
  setTimeout(buildUi,1000);
  setTimeout(setVersion,1000);

  window.tt205BuildQuickFormation=buildUi;
})();

