/* === v231-fullscreen-undo-reset-board ===
   Bas: 230.
   Lägger till helskärmsknappar i Formation:
   - ↶ ångra
   - ↻ återställ tavlan = rensa ritningar + standardpositioner
   Rör inte Taktikfilm, Matcher, sparning, statistik eller laguppställning.
*/
(function(){
  if(window.__tt231FullscreenUndoResetBoard)return;
  window.__tt231FullscreenUndoResetBoard=true;

  function setVersion(){
    try{
      document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]').forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function inFullscreenFormation(){
    try{return document.body.classList.contains("fullscreen-portrait") && !!document.getElementById("fs-top-tools");}
    catch(e){return false;}
  }

  function currentFormationName(){
    try{
      var active=document.querySelector("#formation-btns .btn.on");
      if(active && active.textContent)return active.textContent.trim();
    }catch(e){}
    try{if(typeof _defaultFormation!=="undefined" && _defaultFormation)return _defaultFormation;}catch(e){}
    return "4-4-2";
  }

  function clearDrawingsOnly(){
    try{arrows=[];}catch(e){}
    try{labels=[];}catch(e){}
    try{freehandPaths=[];}catch(e){}
    try{zones=[];}catch(e){}
    try{tempArrow=null;}catch(e){}
    try{currentFreehand=null;}catch(e){}
    try{draftZone=null;}catch(e){}
  }

  function saveUndoSafe(){
    try{if(typeof saveUndo==="function"){saveUndo();return;}}catch(e){}
    try{if(typeof pushUndo==="function"){pushUndo();return;}}catch(e){}
  }

  function undoSafe(){
    try{if(typeof undo==="function"){undo();return true;}}catch(e){}
    try{if(typeof doUndo==="function"){doUndo();return true;}}catch(e){}
    try{
      var btn=document.getElementById("btn-undo") ||
        document.querySelector("[data-action='undo']") ||
        Array.from(document.querySelectorAll("button")).find(function(b){
          var txt=String(b.textContent||"").trim().toLowerCase();
          return txt==="↶" || txt.indexOf("ångra")>=0;
        });
      if(btn){btn.click();return true;}
    }catch(e){}
    return false;
  }

  function resetPlayersToStandard(){
    var f=currentFormationName();
    try{if(typeof initPlayers==="function"){initPlayers(f);return true;}}catch(e){}
    try{
      var stdBtn=Array.from(document.querySelectorAll("button")).find(function(b){
        var txt=String(b.textContent||"").trim().toLowerCase();
        return txt==="standard" || txt.indexOf("standard")>=0;
      });
      if(stdBtn){stdBtn.click();return true;}
    }catch(e){}
    return false;
  }

  function resetBoard(){
    saveUndoSafe();
    clearDrawingsOnly();
    resetPlayersToStandard();
    try{if(typeof render==="function")render();}catch(e){}
    try{if(typeof syncFullscreenToolButtons==="function")syncFullscreenToolButtons();}catch(e){}
    try{if(typeof tt230PlaceDrawingOptionsEvenHigher==="function")tt230PlaceDrawingOptionsEvenHigher();}catch(e){}
    try{showToast("Tavlan återställd");}catch(e){}
  }

  function injectStyle(){
    if(document.getElementById("tt231-style"))return;
    var st=document.createElement("style");
    st.id="tt231-style";
    st.textContent=[
      "body.fullscreen-portrait #fs-top-tools .tt231-reset{color:#e8c84a!important;border-color:#e8c84a!important}",
      "body.fullscreen-portrait #fs-top-tools .tt231-undo{color:#4ae87a!important;border-color:#4ae87a!important}"
    ].join("\n");
    document.head.appendChild(st);
  }

  function findEraserButton(tools){
    try{
      return Array.from(tools.querySelectorAll("button")).find(function(b){
        var txt=String(b.textContent||"").trim().toLowerCase();
        var title=String(b.title||"").toLowerCase();
        var id=String(b.id||"").toLowerCase();
        return txt==="⌫" || txt==="🧽" || txt==="⌧" ||
          txt.indexOf("sudd")>=0 || title.indexOf("sudd")>=0 ||
          title.indexOf("rensa")>=0 || id.indexOf("eraser")>=0 ||
          id.indexOf("clear")>=0;
      });
    }catch(e){return null;}
  }

  function addButtons(){
    setVersion();
    injectStyle();
    var tools=document.getElementById("fs-top-tools");
    if(!tools)return;
    if(document.getElementById("tt231-fs-undo") && document.getElementById("tt231-fs-reset"))return;

    var eraser=findEraserButton(tools);

    function makeToolbarTwin(id,txt,title,extraClass,color){
      var b=document.createElement("button");
      b.id=id;
      b.type="button";
      b.className=(eraser&&eraser.className?eraser.className:"ls-btn")+" "+extraClass;
      if(eraser&&eraser.getAttribute("style"))b.style.cssText=eraser.getAttribute("style");
      b.classList.remove("on");
      b.textContent=txt;
      b.title=title;
      b.style.color=color;
      b.style.borderColor=color;
      return b;
    }

    var undoBtn=makeToolbarTwin("tt231-fs-undo","↶","Ångra","tt231-undo","#4ae87a");
    undoBtn.addEventListener("click",function(e){
      e.preventDefault(); e.stopPropagation(); if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      if(!undoSafe()){try{showToast("Inget att ångra");}catch(err){}}
      try{if(typeof render==="function")render();}catch(err2){}
      return false;
    },true);

    var resetBtn=makeToolbarTwin("tt231-fs-reset","↻","Återställ tavlan","tt231-reset","#e8c84a");
    resetBtn.addEventListener("click",function(e){
      e.preventDefault(); e.stopPropagation(); if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      resetBoard();
      return false;
    },true);

    if(eraser && eraser.parentNode===tools){
      tools.insertBefore(undoBtn,eraser.nextSibling);
      tools.insertBefore(resetBtn,undoBtn.nextSibling);
    }else{
      tools.appendChild(undoBtn);
      tools.appendChild(resetBtn);
    }
  }

  var oldSync=typeof syncFullscreenToolButtons==="function" ? syncFullscreenToolButtons : null;
  if(oldSync && !oldSync.__tt231Wrapped){
    var syncWrapped=function(){
      var res=oldSync.apply(this,arguments);
      if(inFullscreenFormation())addButtons();
      return res;
    };
    syncWrapped.__tt231Wrapped=true;
    syncFullscreenToolButtons=syncWrapped;
    window.syncFullscreenToolButtons=syncWrapped;
  }

  var oldEnter=typeof enterFullscreenPortrait==="function" ? enterFullscreenPortrait : null;
  if(oldEnter && !oldEnter.__tt231Wrapped){
    var enterWrapped=function(){
      var res=oldEnter.apply(this,arguments);
      setTimeout(addButtons,0);
      setTimeout(addButtons,120);
      return res;
    };
    enterWrapped.__tt231Wrapped=true;
    enterFullscreenPortrait=enterWrapped;
    window.enterFullscreenPortrait=enterWrapped;
  }

  function apply(){
    setVersion();
    injectStyle();
    if(inFullscreenFormation())addButtons();
  }

  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",apply);
  else apply();

  setTimeout(apply,300);
  setTimeout(apply,1000);

  window.tt231ResetFullscreenBoard=resetBoard;
  window.tt231AddFullscreenButtons=addButtons;
})();
/* === slut v231-fullscreen-undo-reset-board === */


/* === v237-tavla-rita-toolbar ===
   Bas: 234.
   - Byter endast visad menytext "Formation" -> "Tavla".
   - Behåller Rita-knappen och lägger ritverktygen i samma rad under Rita.
   - Ordning på Tavla: flytta, pil, frihand, zon, text, sudda, ångra, återställ.
   - Rörelsepil döljs i Tavla men lämnas orörd för Taktikfilm.
   - Döljer gamla dubbla återställnings-/rensa-/ångra-knappar i huvudmenyn.
*/
(function(){
  if(window.__tt237TavlaRitaToolbar)return;
  window.__tt237TavlaRitaToolbar=true;

  function setVersion236(){
    try{
      document.querySelectorAll('span[style*="font-size:0.6rem"][style*="letter-spacing"]').forEach(function(s){
        var t=(s.textContent||"").trim();
        if(/^(v?\d+|v3\.)/i.test(t))s.textContent='325';
      });
    }catch(e){}
  }

  function renameFormationToTavla236(){
    try{
      document.querySelectorAll("button,.tab,[role='tab'],a,span,label").forEach(function(el){
        var txt=(el.textContent||"").trim();
        if(txt==="Formation")el.textContent="Tavla";
        var title=(el.getAttribute("title")||"").trim();
        if(title==="Formation")el.setAttribute("title","Tavla");
        var aria=(el.getAttribute("aria-label")||"").trim();
        if(aria==="Formation")el.setAttribute("aria-label","Tavla");
      });
    }catch(e){}
  }

  function drawToolsParent236(){
    var ref=document.getElementById("btn-freehand")||document.getElementById("btn-arrow")||document.getElementById("btn-text")||document.getElementById("btn-zone");
    return ref&&ref.parentNode?ref.parentNode:null;
  }

  function showRitaButton236(){
    try{
      document.querySelectorAll("button,.btn").forEach(function(el){
        var txt=(el.textContent||"").trim().toLowerCase();
        var title=(el.getAttribute("title")||"").trim().toLowerCase();
        if(txt==="rita" || title==="rita"){
          el.style.display="";
          if(el.dataset)delete el.dataset.tt235Hidden;
        }
      });
    }catch(e){}
  }

  function hideOldMainButton236(el){
    if(!el)return;
    el.style.display="none";
    if(el.dataset)el.dataset.tt236Hidden="1";
  }

  function hideDuplicateMainControls236(){
    try{
      hideOldMainButton236(document.getElementById("btn-reset"));
      hideOldMainButton236(document.getElementById("btn-standard-reset"));
      hideOldMainButton236(document.getElementById("btn-undo"));
      var bar=drawToolsParent236();
      if(!bar)return;
      Array.from(bar.children).forEach(function(el){
        if(!el || el.id && /^tt236-/.test(el.id))return;
        var txt=(el.textContent||"").trim().toLowerCase();
        var id=(el.id||"").toLowerCase();
        if(id==="btn-reset" || id==="btn-standard-reset" || id==="btn-undo")hideOldMainButton236(el);
        // Den gamla skapade Rensa-knappen återställer även spelare, så den ersätts av en riktig suddknapp.
        if(txt==="rensa" || txt==="↺ standard" || txt==="standard")hideOldMainButton236(el);
      });
    }catch(e){}
  }

  function isTaktikActive236(){
    try{
      var tab=document.querySelector('.tab.on[data-panel="taktik"]');
      return !!(tab || playback || isEditingTaktik || editingTaktikIdx!==null);
    }catch(e){return false;}
  }

  function clearDrawingsOnly236(){
    try{if(typeof saveUndo==="function")saveUndo();}catch(e){}
    try{arrows=[];}catch(e){}
    try{labels=[];}catch(e){}
    try{freehandPaths=[];}catch(e){}
    try{zones=[];}catch(e){}
    try{movementPaths=[];}catch(e){}
    try{selectedId=null;arrowStart=null;arrowCurrent=null;freehandCurrent=null;freehandDrawing=false;zoneStart=null;zonePreview=null;movementCurrent=null;}catch(e){}
    try{if(typeof setMode==="function")setMode("move");}catch(e){}
    try{if(typeof render==="function")render();}catch(e){}
    try{showToast("Ritningar rensade");}catch(e){}
  }

  function resetBoard236(){
    try{
      if(typeof window.tt231ResetFullscreenBoard==="function"){
        window.tt231ResetFullscreenBoard();
        return;
      }
    }catch(e){}
    try{if(typeof clearCoachboardToFormation==="function")clearCoachboardToFormation();}catch(e){}
  }

  function iconFromFullscreen236(fsId,fallback){
    try{
      var fs=document.getElementById(fsId);
      var t=fs?(fs.textContent||"").trim():"";
      return t||fallback;
    }catch(e){return fallback;}
  }

  function prepExistingTool236(id,fsId,fallback,title){
    var b=document.getElementById(id);
    if(!b)return null;
    b.classList.add("tt236-rita-tool");
    b.textContent=iconFromFullscreen236(fsId,fallback);
    b.title=title;
    b.setAttribute("aria-label",title);
    b.style.display="";
    return b;
  }

  function makeRitaButton236(id,txt,title,handler){
    var b=document.getElementById(id);
    if(!b){
      b=document.createElement("button");
      b.id=id;
      b.type="button";
    }
    b.className="btn tt236-rita-tool";
    b.textContent=txt;
    b.title=title;
    b.setAttribute("aria-label",title);
    b.style.display="";
    if(!b.dataset.tt236Bound){
      b.dataset.tt236Bound="1";
      b.addEventListener("click",function(e){
        e.preventDefault();
        e.stopPropagation();
        handler(e);
        syncRitaToolState236();
      });
    }
    return b;
  }

  function syncRitaToolState236(){
    try{
      var map={"btn-arrow":"arrow","btn-freehand":"freehand","btn-zone":"zone","btn-text":"text"};
      Object.keys(map).forEach(function(id){
        var b=document.getElementById(id);
        if(!b)return;
        b.classList.toggle("on",mode===map[id]);
        b.classList.toggle("active",mode===map[id]);
      });
      var move=document.getElementById("tt236-rita-move");
      if(move){move.classList.toggle("on",mode==="move");move.classList.toggle("active",mode==="move");}
      var mv=document.getElementById("btn-movement");
      if(mv){
        mv.classList.add("tt236-rita-tool");
        if(isTaktikActive236()){
          mv.style.removeProperty("display");
        }else{
          // Viktigt: CSS-klassen har display: inline-flex !important, så vanlig display=none räcker inte.
          mv.style.setProperty("display","none","important");
        }
        mv.classList.toggle("on",mode==="movement");
        mv.classList.toggle("active",mode==="movement");
      }
    }catch(e){}
  }

  function injectStyle236(){
    if(document.getElementById("tt236-rita-style"))return;
    var st=document.createElement("style");
    st.id="tt236-rita-style";
    st.textContent=[
      ".tt236-rita-tool{min-width:34px!important;width:34px!important;height:32px!important;padding:4px 7px!important;box-sizing:border-box!important;font-size:.85rem!important;line-height:1!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;flex:0 0 auto!important}",
      ".tt236-rita-tool.on,.tt236-rita-tool.active{border-color:#4ae87a!important;color:#4ae87a!important;background:rgba(74,232,122,.08)!important}",
      "#tt236-rita-clear{color:#e8c84a!important;border-color:#e8c84a!important}",
      "#tt236-rita-undo{color:#4ae87a!important;border-color:#4ae87a!important}",
      "#tt236-rita-reset{color:#e8c84a!important;border-color:#e8c84a!important}",
      "@media(max-width:760px){.tt236-rita-tool{min-width:32px!important;width:32px!important;height:30px!important;padding:3px 6px!important;font-size:.8rem!important}}"
    ].join("\n");
    document.head.appendChild(st);
  }

  function placeRitaTools236(){
    var bar=drawToolsParent236();
    if(!bar)return;

    var move=makeRitaButton236("tt236-rita-move","✋","Flytta spelare/boll",function(){try{setMode("move");}catch(e){}});
    var arrow=prepExistingTool236("btn-arrow","fs-tb-arrow","↗","Pil");
    var free=prepExistingTool236("btn-freehand","fs-tb-freehand","✎","Rita fritt");
    var zone=prepExistingTool236("btn-zone","fs-tb-zone","▭","Zon");
    var text=prepExistingTool236("btn-text","fs-tb-text","T","Text");
    var clear=makeRitaButton236("tt236-rita-clear","🧽","Sudda/rensa ritningar",clearDrawingsOnly236);
    var undo=makeRitaButton236("tt236-rita-undo","↶","Ångra",function(){try{if(typeof doUndo==="function")doUndo();}catch(e){}});
    var reset=makeRitaButton236("tt236-rita-reset","↻","Återställ tavlan",resetBoard236);

    // Exakt Tavla-ordning enligt helskärmsraden, men utan rörelsepil och utan dagsljus.
    [move,arrow,free,zone,text,clear,undo,reset].forEach(function(b){
      if(b)bar.appendChild(b);
    });

    // Rörelsepil finns kvar för Taktikfilm, men ska inte synas på Tavla.
    var mv=document.getElementById("btn-movement");
    if(mv){
      mv.classList.add("tt236-rita-tool");
      mv.title="Rörelsebana";
      mv.setAttribute("aria-label","Rörelsebana");
      if(isTaktikActive236()){
        mv.style.removeProperty("display");
        bar.appendChild(mv);
      }else{
        // På Tavla ska rörelsepilens knapp inte synas alls, men funktionen lämnas orörd för Taktikfilm.
        mv.style.setProperty("display","none","important");
      }
    }

    hideDuplicateMainControls236();
    showRitaButton236();
    syncRitaToolState236();
  }

  var oldSetMode236=typeof setMode==="function"?setMode:null;
  if(oldSetMode236 && !oldSetMode236.__tt236Wrapped){
    var wrappedSetMode236=function(){
      var res=oldSetMode236.apply(this,arguments);
      syncRitaToolState236();
      return res;
    };
    wrappedSetMode236.__tt236Wrapped=true;
    setMode=wrappedSetMode236;
    window.setMode=wrappedSetMode236;
  }

  var oldBuildFormationBtns236=typeof buildFormationBtns==="function"?buildFormationBtns:null;
  if(oldBuildFormationBtns236 && !oldBuildFormationBtns236.__tt236Wrapped){
    var wrappedBuildFormationBtns236=function(){
      var res=oldBuildFormationBtns236.apply(this,arguments);
      renameFormationToTavla236();
      return res;
    };
    wrappedBuildFormationBtns236.__tt236Wrapped=true;
    buildFormationBtns=wrappedBuildFormationBtns236;
    window.buildFormationBtns=wrappedBuildFormationBtns236;
  }

  function apply236(){
    setVersion236();
    injectStyle236();
    renameFormationToTavla236();
    placeRitaTools236();
  }

  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",apply236);
  else apply236();

  document.addEventListener("click",function(ev){
    try{
      if(ev&&ev.target&&ev.target.closest&&ev.target.closest('#arrow-options,#freehand-options,#zone-options,#tt252-ipad-rita-row'))return;
    }catch(e){}
    setTimeout(function(){
      setVersion236();
      renameFormationToTavla236();
      placeRitaTools236();
    },0);
  },true);
  setTimeout(apply236,300);
  setTimeout(apply236,1000);

  window.tt236ApplyTavlaRitaToolbar=apply236;
})();
